// scripts/validate-secrets.js
const secretsFiles = ['.env', '.env.test', '.env.production'];

const canaryPatterns = [
  /CANARY/i,
  /test-credential/i,
  /example\.com/i,
  /your_key_here/i
];

function validateSecretsFile(filePath) {
  const fs = require('fs');

  if (!fs.existsSync(filePath)) {
    console.log(`⚠️  File not found: ${filePath}`);
    return;
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n');
  const issues = [];

  // Check for world-readable
  const stats = fs.statSync(filePath);
  const mode = (stats.mode & parseInt('777', 8)).toString(8);
  if (mode !== '600' && mode !== '400') {
    issues.push(`Insecure permissions: ${mode} (should be 600)`);
  }

  // Check for canary/test values
  lines.forEach((line, index) => {
    if (line.includes('=') && !line.startsWith('#')) {
      const [key, value] = line.split('=');
      canaryPatterns.forEach(pattern => {
        if (pattern.test(value)) {
          issues.push(`Line ${index + 1}: ${key} contains test value`);
        }
      });
    }
  });

  // Check for weak secrets
  lines.forEach((line, index) => {
    if (line.includes('=') && !line.startsWith('#')) {
      const [key, value] = line.split('=');
      if (value.length < 16 && !value.includes('"')) {
        issues.push(`Line ${index + 1}: ${key} appears weak (too short)`);
      }
    }
  });

  return issues;
}

console.log('🔍 Validating secrets files...\n');

secretsFiles.forEach(file => {
  console.log(`Checking ${file}:`);
  const issues = validateSecretsFile(file);

  if (issues.length === 0) {
    console.log('  ✅ No issues found\n');
  } else {
    console.log('  ❌ Issues found:');
    issues.forEach(issue => console.log(`     - ${issue}`));
    console.log('');
  }
});
```

