#!/usr/bin/env node

/**
 * Security Audit Script for Environment Variables
 * Run this in CI/CD to detect secrets management issues
 */

const fs = require('fs');
const path = require('path');

const SEVERITY = {
  CRITICAL: 'CRITICAL',
  HIGH: 'HIGH',
  MEDIUM: 'MEDIUM',
  LOW: 'LOW'
};

const issues = [];

// Check 1: .env files committed
function checkEnvFilesCommitted() {
  const envFiles = ['.env', '.env.local', '.env.production', '.env.development'];

  envFiles.forEach(file => {
    if (fs.existsSync(file)) {
      issues.push({
        severity: SEVERITY.CRITICAL,
        check: 'ENV_FILE_EXISTS',
        message: `.env file '${file}' exists in working directory`,
        recommendation: 'Remove .env files from version control and add to .gitignore'
      });
    }
  });
}

// Check 2: .gitignore configuration
function checkGitignore() {
  if (!fs.existsSync('.gitignore')) {
    issues.push({
      severity: SEVERITY.HIGH,
      check: 'NO_GITIGNORE',
      message: 'No .gitignore file found',
      recommendation: 'Create .gitignore with .env, .env.* patterns'
    });
    return;
  }

  const gitignore = fs.readFileSync('.gitignore', 'utf8');

  if (!gitignore.includes('.env')) {
    issues.push({
      severity: SEVERITY.HIGH,
      check: 'ENV_NOT_GITIGNORED',
      message: '.env files not properly ignored in .gitignore',
      recommendation: 'Add ".env" and ".env.*" to .gitignore'
    });
  }
}

// Check 3: Hardcoded secrets in code
function checkHardcodedSecrets() {
  const jsFiles = findFiles('.', '.js');

  jsFiles.forEach(file => {
    const content = fs.readFileSync(file, 'utf8');

    // Check for common secret patterns
    const patterns = [
      { name: 'API Key', regex: /(api[_-]?key\s*=\s*['"])[^'"]{20,}/gi },
      { name: 'AWS Key', regex: /(aws[_-]?secret[_-]?access[_-]?key\s*=\s*['"])[^'"]{20,}/gi },
      { name: 'Database URL', regex: /(database[_-]?url\s*=\s*['"])[^'"]*(password|admin)[^'"]*['"]/gi },
      { name: 'JWT Secret', regex: /(jwt[_-]?secret\s*=\s*['"])[^'"]{20,}/gi },
      { name: 'Stripe Key', regex: /(stripe[_-]?secret[_-]?key\s*=\s*['"])[^'"]{20,}/gi }
    ];

    patterns.forEach(pattern => {
      const matches = content.match(pattern.regex);
      if (matches) {
        issues.push({
          severity: SEVERITY.CRITICAL,
          check: 'HARDCODED_SECRET',
          message: `Potential ${pattern.name} found in ${file}`,
          recommendation: 'Move secrets to environment variables or secrets manager'
        });
      }
    });
  });
}

// Check 4: dotenv validation
function checkDotenvUsage() {
  const packageJsonPath = path.join(process.cwd(), 'package.json');

  if (fs.existsSync(packageJsonPath)) {
    const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
    const hasDotenv = packageJson.dependencies?.dotenv || packageJson.devDependencies?.dotenv;

    if (!hasDotenv) {
      issues.push({
        severity: SEVERITY.MEDIUM,
        check: 'NO_DOTENV',
        message: 'dotenv package not installed',
        recommendation: 'Install dotenv and configure it at the top of app.js'
      });
    }
  }
}

// Check 5: App.js configuration
function checkAppConfig() {
  const appPath = path.join(process.cwd(), 'app.js');

  if (fs.existsSync(appPath)) {
    const content = fs.readFileSync(appPath, 'utf8');

    if (!content.includes('dotenv.config()') && !content.includes('require(\'dotenv\')')) {
      issues.push({
        severity: SEVERITY.HIGH,
        check: 'NO_DOTENV_CONFIG',
        message: 'app.js does not load environment variables via dotenv',
        recommendation: 'Add require("dotenv").config() at the top of app.js'
      });
    }

    // Check for hard-coded port
    const hardCodedPort = content.match(/\.listen\((\d+)\s*,/);
    if (hardCodedPort && !content.includes('process.env.PORT')) {
      issues.push({
        severity: SEVERITY.LOW,
        check: 'HARDCODED_PORT',
        message: `Port is hard-coded to ${hardCodedPort[1]}`,
        recommendation: 'Use process.env.PORT or an environment variable'
      });
    }
  }
}

// Helper: Find files recursively
function findFiles(dir, extension) {
  const files = [];

  function scan(currentDir) {
    const items = fs.readdirSync(currentDir);

    items.forEach(item => {
      const fullPath = path.join(currentDir, item);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory() && !item.startsWith('.') && item !== 'node_modules') {
        scan(fullPath);
      } else if (item.endsWith(extension)) {
        files.push(fullPath);
      }
    });
  }

  scan(dir);
  return files;
}

// Run all checks
function runAudit() {
  console.log('🔍 Running Secrets Management Security Audit...\n');

  checkEnvFilesCommitted();
  checkGitignore();
  checkHardcodedSecrets();
  checkDotenvUsage();
  checkAppConfig();

  // Display results
  if (issues.length === 0) {
    console.log('✅ No security issues found!\n');
    return 0;
  }

  // Group by severity
  const bySeverity = {
    [SEVERITY.CRITICAL]: [],
    [SEVERITY.HIGH]: [],
    [SEVERITY.MEDIUM]: [],
    [SEVERITY.LOW]: []
  };

  issues.forEach(issue => {
    bySeverity[issue.severity].push(issue);
  });

  // Print results
  Object.entries(bySeverity).forEach(([severity, severityIssues]) => {
    if (severityIssues.length > 0) {
      const emoji = severity === SEVERITY.CRITICAL ? '🚨' : 
                    severity === SEVERITY.HIGH ? '⚠️' :
                    severity === SEVERITY.MEDIUM ? '🟡' : '🟢';

      console.log(`${emoji} ${severity} (${severityIssues.length} issues):`);
      severityIssues.forEach(issue => {
        console.log(`   [${issue.check}] ${issue.message}`);
        console.log(`   → ${issue.recommendation}\n`);
      });
    }
  });

  console.log(`\n📊 Total Issues: ${issues.length} (${bySeverity[SEVERITY.CRITICAL].length} critical)`);

  // Exit with error code if critical issues found
  return bySeverity[SEVERITY.CRITICAL].length > 0 ? 1 : 0;
}

// Run if executed directly
if (require.main === module) {
  const exitCode = runAudit();
  process.exit(exitCode);
}

module.exports = { runAudit };

