// Create config/secrets.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({ region: process.env.AWS_REGION });

async function getSecret(secretName) {
  try {
    const data = await client.getSecretValue({ SecretId: secretName }).promise();
    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    }
    // For binary secrets
    return Buffer.from(data.SecretBinary, 'base64').toString();
  } catch (err) {
    if (err.code === 'DecryptionFailureException') {
      throw new Error('Secrets Manager cannot decrypt the protected secret');
    }
    throw err;
  }
}

