### Step 5: Add Runtime Secret Validation

```javascript
// security/secretValidator.js

class SecretValidator {
  constructor() {
    this.rules = {
      DATABASE_URL: {
        required: ['production', 'staging'],
        pattern: /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/\w+$/,
        description: 'Valid PostgreSQL connection string'
      },
      STRIPE_SECRET_KEY: {
        required: ['production'],
        pattern: /^(sk_live_|sk_test_)[a-zA-Z0-9]{24,}$/,
        description: 'Valid Stripe secret key'
      },
      AWS_ACCESS_KEY_ID: {
        required: ['production', 'staging'],
        pattern: /^AKIA[0-9A-Z]{16}$/,
        description: 'Valid AWS access key ID'
      },
      AWS_SECRET_ACCESS_KEY: {
        required: ['production', 'staging'],
        minLength: 40,
        description: 'AWS secret access key'
      }
    };
  }

  validate(env = process.env) {
    const nodeEnv = env.NODE_ENV || 'development';
    const errors = [];
    const warnings = [];

    for (const [key, rule] of Object.entries(this.rules)) {
      const value = env[key];

      // Check if required
      if (rule.required.includes(nodeEnv)) {
        if (!value) {
          errors.push(`Missing required secret: ${key}`);
          continue;
        }
      }

      if (!value) continue;

      // Check pattern
      if (rule.pattern && !rule.pattern.test(value)) {
        errors.push(
          `Invalid format for ${key}: ${rule.description}`
        );
      }

      // Check for test/canary values in production
      if (nodeEnv === 'production' && /CANARY|test|placeholder/i.test(value)) {
        errors.push(
          `CRITICAL: Test/canary value detected for ${key} in production`
        );
      }

      // Check for leaked secrets in error messages
      if (value.length < 20 && key.includes('KEY') && key.includes('SECRET')) {
        warnings.push(
          `Secret ${key} seems too short (${value.length} chars)`
        );
      }
    }

    return { errors, warnings };
  }
}

module.exports = SecretValidator;
```

