// Prevent secrets from appearing in logs
function sanitizeForLogging(obj) {
  const sanitized = { ...obj };
  const secretKeys = [
    'password', 'secret', 'token', 'key', 'auth',
    'DATABASE_URL', 'AWS_SECRET_ACCESS_KEY', 'STRIPE_SECRET_KEY',
    'ANTHROPIC_API_KEY', 'LOGFIRE_TOKEN'
