### Step 7: Pre-commit Hook for Secret Detection

```bash
#!/bin/bash
# .git/hooks/pre-commit

echo "Scanning for secrets..."

# Patterns for common secrets
SECRET_PATTERNS=(
  "AKIA[0-9A-Z]{16}"           # AWS Access Key
  "sk_live_[a-zA-Z0-9]{24,}"   # Stripe Live Key
  "sk_test_[a-zA-Z0-9]{24,}"   # Stripe Test Key
  "postgresql://[^:]+:[^@]+@"  # PostgreSQL URL
  "mongodb://[^:]+:[^@]+@"     # MongoDB URL
  "mysql://[^:]+:[^@]+@"       # MySQL URL
  "AIza[0-9A-Za-z\\-_]{35}"    # Google API Key
  "sk-ant-[a-zA-Z0-9-]{40,}"   # Anthropic API Key
)

FOUND_SECRETS=0

for pattern in "${SECRET_PATTERNS[@]}"; do
  if git diff --cached --name-only -z | xargs -0 grep -E "$pattern" 2>/dev/null; then
    echo "⚠️  Potential secret found matching pattern: $pattern"
    FOUND_SECRETS=1
  fi
done

if [ $FOUND_SECRETS -eq 1 ]; then
  echo ""
  echo "❌ Commit blocked: Potential secrets detected in staged files!"
  echo "   Remove sensitive data and try again."
  exit 1
fi

echo "✓ No secrets detected"
exit 0
```

