function sendRotationNotification(endpointUrl, credentialList) {
  return new Promise((resolve, reject) => {
    // Send ONLY metadata - no actual values
    const payload = {
      event_type: 'credential_rotation',
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV,
      rotation_id: crypto.randomUUID(),
      credentials: credentialList.map(cred => ({
