        hash: crypto.createHash('sha256').update('rotated').digest('hex')
      })),
      // No actual secret values
      ticket_reference: 'SEC-2024-06-22-001'
    };

    const options = {
      hostname: new URL(endpointUrl).hostname,
      port: new URL(endpointUrl).port || 443,
      path: new URL(endpointUrl).pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(JSON.stringify(payload))
      }
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        if (res.statusCode === 200) {
          resolve(JSON.parse(data));
        } else {
          reject(new Error(`Webhook failed: ${res.statusCode}`));
        }
      });
    });

    req.on('error', reject);
    req.write(JSON.stringify(payload));
    req.end();
  });
}

// Usage - sends metadata only
sendRotationNotification(
  'https://your-compliance-system.example.com/api/rotation-log',
