```javascript
const AWS = require('aws-sdk');
const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

class SecretLoader {
  constructor(region = process.env.AWS_REGION || 'us-east-1') {
    this.client = new SecretsManager({ region });
    this.cache = new Map();
    this.cacheTimeout = 300000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTimeout) {
        return JSON.parse(cached.value);
      }
    }

    try {
      const response = await this.client.getSecretValue({
        SecretId: secretName
      });

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = JSON.parse(Buffer.from(response.SecretBinary, 'base64').toString());
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: JSON.stringify(secret),
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Error fetching secret ${secretName}:`, error);
      throw new Error(`Failed to load secret: ${secretName}`);
    }
  }

  async getAllSecrets(secretNames) {
    const secrets = {};
    await Promise.all(
      secretNames.map(async (name) => {
        secrets[name] = await this.getSecret(name);
      })
    );
    return secrets;
  }
}

module.exports = SecretLoader;
```

