### **Option 2: HashiCorp Vault**

Create `config/vault.js`:

```javascript
const nodeVault = require('node-vault');

class VaultSecretLoader {
  constructor() {
    this.vault = nodeVault({
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN
    });
  }

  async loadSecret(path, key) {
    try {
      const result = await this.vault.read(`secret/data/${path}`);
      return result.data.data[key];
    } catch (error) {
      console.error(`Vault error reading ${path}/${key}:`, error.message);
      throw error;
    }
  }

  async loadMultipleSecrets(secretsConfig) {
    const secrets = {};

    for (const [envVar, vaultPath] of Object.entries(secretsConfig)) {
      const [path, key] = vaultPath.split('.');
      secrets[envVar] = await this.loadSecret(path, key);
    }

    return secrets;
  }
}

module.exports = VaultSecretLoader;
```

