const { SSM } = require('@aws-sdk/client-ssm');

class ParameterStoreLoader {
  constructor(region = process.env.AWS_REGION || 'us-east-1') {
    this.ssm = new SSM({ region });
  }

  async getParameter(name, withDecryption = true) {
    try {
      const response = await this.ssm.getParameter({
        Name: name,
        WithDecryption: withDecryption
      });
      return response.Parameter.Value;
    } catch (error) {
      console.error(`Error fetching parameter ${name}:`, error.message);
      throw error;
    }
  }

  async getParametersByPath(path) {
    try {
      const response = await this.ssm.getParametersByPath({
        Path: path,
        WithDecryption: true,
        Recursive: true
      });
      return response.Parameters;
    } catch (error) {
      console.error(`Error fetching path ${path}:`, error.message);
      throw error;
    }
  }

  async loadAllParameters() {
    const parameters = await this.getParametersByPath('/prod/app/');
    const secrets = {};

    parameters.forEach(param => {
      const key = param.Name.split('/').pop().toUpperCase();
      secrets[key] = param.Value;
    });

    return secrets;
  }
}

module.exports = ParameterStoreLoader;
