  const region = process.env.AWS_REGION || 'us-east-1';
  const env = process.env.NODE_ENV || 'development';

  const secretPrefix = env === 'production' ? 'prod' : 'dev';

  return new SecretLoader(region, secretPrefix);
};

const loadAndValidateSecrets = async () => {
  try {
