    // Define what secrets we need
    const requiredSecrets = {
      database: `${loader.secretPrefix}/app/database`,
      apiKeys: `${loader.secretPrefix}/app/api-keys`,
      aws: `${loader.secretPrefix}/app/aws-credentials`
    };

    // Load all secrets
    const secrets = await loader.getMultipleSecrets(Object.values(requiredSecrets));

    // Flatten into process.env
    process.env.DATABASE_URL = secrets.database.url;
    process.env.AWS_ACCESS_KEY_ID = secrets.aws.accessKeyId;
    process.env.AWS_SECRET_ACCESS_KEY = secrets.aws.secretAccessKey;
    process.env.ANTHROPIC_API_KEY = secrets.apiKeys.anthropic;
    process.env.STRIPE_SECRET_KEY = secrets.apiKeys.stripe;
    process.env.LOGFIRE_TOKEN = secrets.apiKeys.logfire;

