// Validation - Required secrets for production
const requiredForProduction = [
  'DATABASE_URL',
  'JWT_SECRET',
  'SESSION_SECRET',
];

const requiredForDevelopment = [];

function validateConfig() {
  const isProduction = config.app.env === 'production';
  const required = isProduction ? requiredForProduction : requiredForDevelopment;

  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(
      `Missing required environment variables: ${missing.join(', ')}\n` +
      `Please set these in your environment or .env file.`
    );
  }

  // Warn about optional but recommended secrets
  const recommended = ['AWS_ACCESS_KEY_ID', 'ANTHROPIC_API_KEY'];
  const missingRecommended = recommended.filter(key => !process.env[key]);

  if (missingRecommended.length > 0) {
    console.warn(`Warning: Optional secrets not set: ${missingRecommended.join(', ')}`);
  }

  // Security checks
  if (isProduction) {
    // Check for canary values in production
    Object.entries(process.env).forEach(([key, value]) => {
      if (value && typeof value === 'string' && value.includes('CANARY')) {
        throw new Error(
          `CRITICAL: Canary value detected in production for ${key}. ` +
          `This indicates test credentials are being used in production!`
        );
      }
    });

    // Check for default/jwt secrets
    if (!config.app.jwtSecret || config.app.jwtSecret.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters in production');
    }

    // Check database URL security
    if (config.database.url && config.database.url.includes('localhost')) {
      console.warn('Warning: Database URL points to localhost in production');
    }
  }

  return true;
}

// Validate on load
try {
  validateConfig();
} catch (error) {
  if (config.app.env === 'production') {
    console.error('Configuration validation failed:', error.message);
    process.exit(1);
  } else {
    console.warn('Configuration warning:', error.message);
  }
}

// Export with safety: don't log secrets
