    }

    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();

      let secret;
      if (data.SecretString) {
        // Parse JSON if possible, otherwise return string
        try {
          secret = JSON.parse(data.SecretString);
        } catch {
          secret = data.SecretString;
        }
      } else if (data.SecretBinary) {
        secret = data.SecretBinary.toString('utf-8');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw new Error(`Failed to retrieve secret: ${error.message}`);
    }
  }

  /**
   * Load all application secrets from Secrets Manager
   * @returns {Promise<Object>}
   */
  async loadAppSecrets() {
    const secrets = {};

    try {
      // Database credentials
      const dbSecret = await this.getSecret('prod/database/credentials');
      secrets.database = dbSecret;

      // API keys
      const apiSecrets = await this.getSecret('prod/api/keys');
      secrets.apiKeys = apiSecrets;

      // JWT/Session secrets
      const authSecrets = await this.getSecret('prod/auth/secrets');
      secrets.auth = authSecrets;

      // Third-party service credentials
      const thirdParty = await this.getSecret('prod/third-party/credentials');
      secrets.thirdParty = thirdParty;

      return secrets;
    } catch (error) {
      console.error('Failed to load secrets from AWS Secrets Manager:', error.message);
      throw error;
    }
  }

  /**
   * Clear the cache (use after secret rotation)
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Get secret with automatic fallback to environment variable
   * Useful for local development where Secrets Manager may not be available
   */
  async getSecretWithFallback(secretName, envVarName) {
    try {
      return await this.getSecret(secretName);
    } catch (error) {
      if (process.env[envVarName]) {
        console.warn(`Using environment variable ${envVarName} instead of ${secretName}`);
        return process.env[envVarName];
      }
      throw error;
    }
  }
}

