/**
 * Secrets Audit Script
 * Scans codebase for hardcoded secrets and secret leakage patterns
 */

const fs = require('fs');
const path = require('path');

// Patterns that indicate hardcoded secrets
const SECRET_PATTERNS = [
  { name: 'API Key', pattern: /(?:api[_-]?key|apikey)\s*[=:]\s*['"](sk_?|AIza|pk_|ak_|AKIA)[a-zA-Z0-9_-]{20,}['"]/gi },
  { name: 'AWS Access Key', pattern: /(?:aws[_-]?access[_-]?key[_-]?id|access[_-]?key)\s*[=:]\s*['"]?AKIA[a-zA-Z0-9]{16}['"]?/gi },
  { name: 'AWS Secret Key', pattern: /(?:aws[_-]?secret[_-]?access[_-]?key|secret[_-]?key)\s*[=:]\s*['"][a-zA-Z0-9+/]{40}['"]/gi },
  { name: 'Database URL', pattern: /(?:database[_-]?url|db[_-]?url|mongo[_-]?uri|postgres[_-]url)\s*[=:]\s*['"]?(?:postgres|mysql|mongodb|mssql):\/\/[^'"\s]+/gi },
  { name: 'Password', pattern: /(?:password|passwd|secret)\s*[=:]\s*['"][^'"\s]{8,}['"]/gi },
  { name: 'JWT Secret', pattern: /jwt[_-]?secret\s*[=:]\s*['"][^'"\s]{20,}['"]/gi },
  { name: 'Private Key', pattern: /-----BEGIN\s+(?:RSA\s+)?PRIVATE\s+KEY-----/gim },
  { name: 'Token', pattern: /(?:token|bearer|auth[_-]?token)\s*[=:]\s*['"][a-zA-Z0-9_-]{32,}['"]/gi },
  { name: 'Canary Value', pattern: /(?:canary|test[_-]?value|dummy)[a-z0-9_-]*\s*[=:]\s*['"][^'"]*canary[^'"]*['"]/gi },
  { name: 'Base64 Encoded Secret', pattern: /['"][A-Za-z0-9+/]{40,}={0,2}['"](?=\s*(?:secret|key|token|password))/gi },
];

// Patterns that indicate potentially insecure paths
const INSECURE_PATHS = [
  /\.env$/,
  /\.env\.local$/,
  /\.env\.[^.]+$/,
  /secrets?\.(json|js|ts)$/,
  /config\/secrets/,
];

// Files/directories to exclude
const EXCLUDE_PATTERNS = [
  /node_modules/,
  /\.git/,
  /coverage/,
  /dist/,
  /build/,
  /\.example$/,
  /\.sample$/,
  /\.template$/,
];

class SecretsAuditor {
  constructor(rootDir = process.cwd()) {
    this.rootDir = rootDir;
    this.findings = [];
    this.scannedFiles = 0;
  }

  /**
   * Scan a directory for secrets
   */
  async audit() {
    console.log(`\n🔍 Auditing ${this.rootDir} for secrets...\n`);

    await this.scanDirectory(this.rootDir);

    this.printReport();

    if (this.findings.length > 0) {
      process.exit(1);
    }
  }

  /**
   * Recursively scan directory
   */
  async scanDirectory(dir, relativePath = '') {
    const entries = fs.readdirSync(dir);

    for (const entry of entries) {
      const fullPath = path.join(dir, entry);
      const relPath = path.join(relativePath, entry);
      const stat = fs.statSync(fullPath);

      // Skip excluded paths
      if (this.shouldExclude(relPath)) {
        continue;
      }

      if (stat.isDirectory()) {
        await this.scanDirectory(fullPath, relPath);
      } else if (stat.isFile()) {
        await this.scanFile(fullPath, relPath);
      }
    }
  }

  /**
   * Check if path should be excluded
   */
  shouldExclude(path) {
    return EXCLUDE_PATTERNS.some(pattern => pattern.test(path));
  }

  /**
   * Scan a single file
   */
  async scanFile(fullPath, relPath) {
    // Check for insecure filenames first
    const insecureFilename = INSECURE_PATHS.find(pattern => pattern.test(relPath));
    if (insecureFilename) {
      this.addFinding({
        severity: 'CRITICAL',
        type: 'Insecure File',
        file: relPath,
        line: 0,
        message: 'File appears to be a secrets file that should be in .gitignore',
        match: relPath
      });
    }

    // Try to read file content
    let content;
    try {
      content = fs.readFileSync(fullPath, 'utf-8');
    } catch (error) {
      return; // Skip files we can't read
    }

    this.scannedFiles++;

    // Check for secret patterns
    const lines = content.split('\n');

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const lineNum = i + 1;

      for (const { name, pattern } of SECRET_PATTERNS) {
        pattern.lastIndex = 0; // Reset regex
        const matches = line.matchAll(pattern);

        for (const match of matches) {
          const isComment = line.trim().startsWith('#');
          const isExample = relPath.includes('.example') || relPath.includes('.sample');

          const severity = this.determineSeverity(name, match[0], isExample);
          if (severity !== 'IGNORE') {
            const redacted = this.redactSecret(match[0]);

            this.addFinding({
              severity,
              type: name,
              file: relPath,
              line: lineNum,
              message: `${name}${isComment ? ' (in comment)' : ''}${isExample ? ' (in example file)' : ''}`,
              match: redacted,
              fullMatch: match[0]
            });
          }
        }
      }
    }
  }

  /**
   * Determine severity based on pattern and context
   */
  determineSeverity(type, match, isExample) {
    const lowerMatch = match.toLowerCase();

    // Canary/test values are warnings
    if (lowerMatch.includes('canary') || lowerMatch.includes('test')) {
      return 'WARNING';
    }

    // Example files get lower severity
    if (isExample) {
      return 'INFO';
    }

    // Critical patterns
    if (['AWS Access Key', 'Private Key', 'AWS Secret Key'].includes(type)) {
      return 'CRITICAL';
    }

    // High severity patterns
    if (['API Key', 'Database URL', 'Password', 'JWT Secret'].includes(type)) {
      return 'HIGH';
    }

    return 'MEDIUM';
  }

  /**
   * Redact secret for display
   */
  redactSecret(secret) {
    if (secret.length <= 10) {
      return '*'.repeat(secret.length);
    }
    return secret.substring(0, 4) + '...' + secret.substring(secret.length - 4);
  }

  /**
   * Add a finding to the list
   */
  addFinding(finding) {
    this.findings.push(finding);
  }

  /**
   * Print the audit report
   */
  printReport() {
    console.log('='.repeat(80));

    // Sort by severity
    const severityOrder = { CRITICAL: 0, HIGH: 1, MEDIUM: 2, WARNING: 3, INFO: 4 };
    this.findings.sort((a, b) => severityOrder[a.severity] - severityOrder[b.severity]);

    // Count by severity
    const counts = this.findings.reduce((acc, f) => {
      acc[f.severity] = (acc[f.severity] || 0) + 1;
      return acc;
    }, {});

    // Print findings
    if (this.findings.length === 0) {
      console.log('✅ No secrets found!\n');
    } else {
      console.log(`⚠️  Found ${this.findings.length} potential secret(s):\n`);

      const emojis = {
        CRITICAL: '🚨',
        HIGH: '🔴',
        MEDIUM: '🟡',
        WARNING: '⚡',
        INFO: 'ℹ️ '
      };

      for (const finding of this.findings) {
        const emoji = emojis[finding.severity] || '⚠️ ';
        console.log(`${emoji} [${finding.severity}] ${finding.type}`);
        console.log(`   File: ${finding.file}:${finding.line}`);
        console.log(`   ${finding.message}`);
        console.log(`   Match: ${finding.match}`);
        console.log();
      }
    }

    console.log('='.repeat(80));
    console.log(`📊 Scanned ${this.scannedFiles} file(s)\n`);

    // Print summary
    if (Object.keys(counts).length > 0) {
      console.log('Severity Summary:');
      for (const [severity, count] of Object.entries(counts)) {
        console.log(`   ${severity}: ${count}`);
      }
      console.log();
    }
  }
}

// Run the audit
const auditor = new SecretsAuditor();
auditor.audit().catch(error => {
  console.error('Audit failed:', error);
  process.exit(1);
});

