```javascript
// 1. Install dependencies
// npm install dotenv @aws-sdk/client-secrets-manager

// 2. Create config.js with fallbacks and validation
const Joi = require('joi');
require('dotenv').config();

const envSchema = Joi.object({
  NODE_ENV: Joi.string().valid('development', 'production', 'test').default('development'),

  // Database
  DATABASE_URL: Joi.string().uri().when('NODE_ENV', {
    is: 'test',
    then: Joi.optional(),
    otherwise: Joi.required()
  }),

  // AWS
  AWS_ACCESS_KEY_ID: Joi.string().when('NODE_ENV', {
    is: 'production',
    then: Joi.forbidden(), // Use IAM roles in production
    otherwise: Joi.optional()
  }),
  AWS_SECRET_ACCESS_KEY: Joi.string().when('NODE_ENV', {
    is: 'production', 
    then: Joi.forbidden(),
    otherwise: Joi.optional()
  }),

  // API Keys
  ANTHROPIC_API_KEY: Joi.string(),
  STRIPE_SECRET_KEY: Joi.string().pattern(/^sk_(test|live)_/),

  // Logfire
  LOGFIRE_TOKEN: Joi.string()
}).unknown();

const { error, value: envVars } = envSchema.validate(process.env, {
  stripUnknown: true,
  abortEarly: false
});

if (error) {
  console.error('Environment configuration error:');
  error.details.forEach(detail => {
    console.error(`  - ${detail.path.join('.')}: ${detail.message}`);
  });
  process.exit(1);
}

// Export validated config
module.exports = {
  env: envVars.NODE_ENV,
  database: {
    url: envVars.DATABASE_URL
  },
  aws: envVars.AWS_ACCESS_KEY_ID ? {
    accessKeyId: envVars.AWS_ACCESS_KEY_ID,
    secretAccessKey: envVars.AWS_SECRET_ACCESS_KEY
  } : undefined,
  api: {
    anthropic: envVars.ANTHROPIC_API_KEY,
    stripe: envVars.STRIPE_SECRET_KEY,
    logfire: envVars.LOGFIRE_TOKEN
  }
};
```

### Production-Ready Secrets Loading

```javascript
// config/production.js - For production environments
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function loadSecrets() {
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

  try {
    // Fetch secrets from AWS Secrets Manager
    const command = new GetSecretValueCommand({
      SecretId: process.env.SECRETS_ARN || 'myapp/production'
    });

    const response = await client.send(command);
    const secrets = JSON.parse(response.SecretString);

    // Set environment variables
    Object.assign(process.env, secrets);

    return secrets;
  } catch (error) {
    if (error.name === 'ResourceNotFoundException') {
      console.warn('Secrets not found in Secrets Manager, falling back to environment');
    } else {
      console.error('Error loading secrets:', error);
      throw error;
    }
  }
}

module.exports = { loadSecrets };
```

