```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Cache secrets to reduce API calls
let secretCache = null;
let cacheExpiry = null;

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
      // Use IAM roles - no hardcoded credentials!
    });
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && secretCache && cacheExpiry && Date.now() < cacheExpiry) {
      return secretCache[secretName];
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      if (response.SecretString) {
        const secret = JSON.parse(response.SecretString);

        // Update cache
        if (!secretCache) secretCache = {};
        secretCache[secretName] = secret;
        cacheExpiry = Date.now() + (5 * 60 * 1000); // 5 minute cache

        return secret;
      } else if (response.SecretBinary) {
        return Buffer.from(response.SecretBinary, 'base64');
      }
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret "${secretName}" not found`);
      }
      throw error;
    }
  }

  async getAllSecrets() {
    // Fetch all required secrets at startup
    const [dbConfig, awsConfig, apiConfig] = await Promise.all([
      this.getSecret('prod/database/config'),
      this.getSecret('prod/aws/credentials'),
      this.getSecret('prod/api/keys'),
    ]);

    return {
      database: dbConfig,
      aws: awsConfig,
      api: apiConfig,
    };
  }
}

module.exports = new SecretsManager();
```

