// config/env-loader.js
const fs = require('fs');
const path = require('path');

/**
 * Add extra security for .env file loading
 * Similar to dotenv but with security hardening
 */
function loadEnvFile(filePath) {
  const resolvedPath = path.resolve(filePath);

  // Security checks
  const stats = fs.statSync(resolvedPath);

  // Must be a regular file
  if (!stats.isFile()) {
    throw new Error(`Not a file: ${resolvedPath}`);
  }

  // Must not be world-readable
  if ((stats.mode & 0o044) !== 0) {
    throw new Error(
      `File is world-readable (insecure). Run: chmod 600 ${resolvedPath}`
    );
  }

  // Must not be world-writable
  if ((stats.mode & 0o022) !== 0) {
    throw new Error(
      `File is world-writable (insecure). Run: chmod 600 ${resolvedPath}`
    );
  }

  // Must be owned by current user (check only works on Unix)
  if (process.getuid && stats.uid !== process.getuid()) {
    console.warn(
      `Warning: File not owned by current user: ${resolvedPath}`
    );
  }

  // Load and parse
  const content = fs.readFileSync(resolvedPath, 'utf8');
  const lines = content.split('\n');

  const env = {};
  lines.forEach(line => {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      if (key) {
        env[key.trim()] = value.trim();
      }
    }
  });

  // Set environment variables
  Object.entries(env).forEach(([key, value]) => {
    if (!process.env[key]) {
      process.env[key] = value;
    }
  });

  return env;
}

// Usage with validation
