const fs = require('fs');
const path = require('path');

const SECRETS_PATH = process.env.SECRETS_PATH || '/var/run/secrets';

function loadK8sSecrets() {
  const secrets = {};

  const secretFiles = {
    databaseUrl: 'database/url',
