  Object.entries(secretFiles).forEach(([key, relativePath]) => {
    const fullPath = path.join(SECRETS_PATH, relativePath);
    if (fs.existsSync(fullPath)) {
      secrets[key] = fs.readFileSync(fullPath, 'utf8').trim();
    }
  });

  return secrets;
}

