// config/rotation.js
const crypto = require('crypto');

class SecretRotator {
  constructor(secretManager) {
    this.manager = secretManager;
    this.rotationInterval = 30 * 24 * 60 * 60 * 1000; // 30 days
  }

  async rotateSecret(secretName) {
