```javascript
const SECRET_MAX_AGE = 90 * 24 * 60 * 60 * 1000; // 90 days

async function checkSecretAge(secretName) {
  const metadata = await secretsManager.describeSecret({ SecretId: secretName });
  const lastChanged = new Date(metadata.LastChangedDate);
  const age = Date.now() - lastChanged.getTime();

  if (age > SECRET_MAX_AGE) {
    console.warn(`⚠️ Secret ${secretName} is ${Math.floor(age / (24*60*60*1000))} days old. Consider rotation.`);
    // Send alert
    await sendSlackAlert(`Secret ${secretName} needs rotation`);
  }
}
