    required: false,
    default: 'false',
    description: 'Put application in maintenance mode',
    isSecret: false,
    parseBoolean: true,
  },
};

// ==================== VALIDATION ====================

/**
 * Validate environment variables
 * @throws {Error} If required secrets are missing or invalid
 */
function validateEnvironment() {
  const errors = [];
  const warnings = [];

  for (const [key, definition] of Object.entries(secretDefinitions)) {
    const value = process.env[key];
    const isSet = value !== undefined && value !== '';

    // Check if required
    if (definition.required && !isSet) {
      errors.push(`${key} is required but not set`);
      continue;
    }

    // Skip validation for optional unset values
    if (!isSet) {
      // Set default if available
      if (definition.default !== undefined) {
        process.env[key] = definition.default;
      }
      continue;
    }

    // Validate using pattern
    if (definition.pattern && !definition.pattern.test(value)) {
      errors.push(`${key} has invalid format`);
    }

    // Validate minimum length
    if (definition.minLength && value.length < definition.minLength) {
      errors.push(
        `${key} must be at least ${definition.minLength} characters ` +
        `(currently ${value.length})`
      );
    }

    // Check for placeholder values in production
    if (config.isProduction && definition.isSecret) {
      const placeholderPatterns = [
        /your-.*-here/i,
        /change.*production/i,
        /placeholder/i,
        /example/i,
        /test/i,
        /canary/i,
      ];
      if (placeholderPatterns.some(p => p.test(value))) {
        errors.push(`${key} appears to be a placeholder value`);
      }
    }

    // Check for length warnings
    if (definition.isSecret && value.length < 16) {
      warnings.push(`${key} is short (${value.length} chars), recommend at least 32`);
    }

    // Check for weak defaults
    if (config.isProduction && definition.isSecret) {
      const weakDefaults = [
        'secret',
        'password',
        'changeme',
        '12345678',
        'qwerty',
      ];
      if (weakDefaults.includes(value.toLowerCase())) {
        errors.push(`${key} is using a weak default value`);
      }
    }
  }

  // Log warnings
  for (const warning of warnings) {
    console.warn(`⚠️  ${warning}`);
  }

  // Fail on errors
  if (errors.length > 0) {
    throw new Error(`Environment validation failed:\n${errors.join('\n')}`);
  }

  console.log(`✅ Environment validated for: ${config.env}`);
  return true;
}

/**
 * Generate a secure random secret
 * @param {number} bytes - Number of bytes (default 32)
 * @returns {string} Hex-encoded random secret
 */
function generateSecret(bytes = 32) {
  return crypto.randomBytes(bytes).toString('hex');
}

// ==================== SECURE CONFIG ACCESS ====================

/**
 * Get a configuration value
 * Secrets are masked in development mode for safety
 */
function get(key) {
  const definition = secretDefinitions[key];

  if (!definition) {
    throw new Error(`Unknown config key: ${key}`);
  }

  const value = process.env[key];

  // Handle boolean flags
  if (definition.parseBoolean) {
    return value === 'true' || value === '1';
  }

  return value;
}

/**
 * Check if a secret is set
 */
function has(key) {
  return isSet(key) || secretDefinitions[key]?.default !== undefined;
}

/**
 * Check if a secret has a value (not just default)
 */
function isSet(key) {
  return process.env[key] !== undefined && process.env[key] !== '';
}

/**
 * Get a safe representation for logging (masks secrets)
 */
function safeGet(key) {
  const definition = secretDefinitions[key];
  const value = process.env[key];

  if (definition?.isSecret && value) {
    return `${value.substring(0, 3)}...${value.substring(value.length - 3)}`;
  }

  return value;
}

/**
 * Get all configuration for display (secrets masked)
 */
function getPublicConfig() {
  const publicConfig = {};

  for (const [key, definition] of Object.entries(secretDefinitions)) {
    publicConfig[key] = definition.isSecret
      ? (isSet(key) ? '*** SET ***' : '*** NOT SET ***')
      : process.env[key];
  }

  return {
    environment: config.env,
    config: publicConfig,
  };
}

// ==================== DATABASE URL PARSING ====================

/**
 * Parse DATABASE_URL into components for TypeORM or Sequelize
 */
function getDatabaseConfig() {
  const url = get('DATABASE_URL');

  try {
    const dbUrl = new URL(url);
    return {
      host: dbUrl.hostname,
      port: parseInt(dbUrl.port, 10) || 5432,
      database: dbUrl.pathname.substring(1),
      username: dbUrl.username,
      password: dbUrl.password,
      ssl: config.isProduction ? { rejectUnauthorized: false } : false,
    };
  } catch (error) {
    throw new Error(`Invalid DATABASE_URL: ${error.message}`);
  }
}

// ==================== SECRET ROTATION SUPPORT ====================

/**
 * Validate a secret meets requirements
 */
function validateSecret(key, value) {
  const definition = secretDefinitions[key];

  if (!definition) {
    return { valid: false, error: 'Unknown secret' };
  }

  if (definition.minLength && value.length < definition.minLength) {
    return {
      valid: false,
      error: `Must be at least ${definition.minLength} characters`,
    };
  }

  if (definition.pattern && !definition.pattern.test(value)) {
    return { valid: false, error: 'Invalid format' };
  }

  return { valid: true };
}

/**
 * Support for graceful secret rotation
 * Allows old and new secrets to work during transition
 */
function getAllowedSecrets(key) {
  const current = process.env[key];
  const oldKey = `${key}_OLD`;

  if (isSet(oldKey)) {
    return [current, process.env[oldKey]];
  }

  return [current];
}

// ==================== EXPORTS ====================

module.exports = {
  // Core config
  config,
  get,
  has,
  isSet,
  safeGet,
  getPublicConfig,

  // Validation
  validateEnvironment,
  validateSecret,
  generateSecret,

  // Database
  getDatabaseConfig,

  // Secret rotation
  getAllowedSecrets,

  // For testing/dev
  loadFromFile: require('dotenv').config,
};

// Validate on import (in production, fail fast)
if (config.isProduction) {
  try {
    validateEnvironment();
  } catch (error) {
    console.error('❌ Environment validation failed:', error.message);
    process.exit(1);
  }
} else {
  // Just warn in development
  try {
    validateEnvironment();
  } catch (error) {
    console.warn('⚠️  Environment validation:', error.message);
  }
}

