          match: match[0],
          truncatedSecret: secret.length > 20
            ? `${secret.substring(0, 8)}...${secret.substring(secret.length - 4)}`
            : secret,
          line: content.substring(0, match.index).split('\n').length,
          context: getContext(content, match.index),
        });
      }
    }

    return findings;
  } catch (error) {
    if (error.code !== 'EISDIR') {
      console.error(`Error reading ${filePath}:`, error.message);
    }
    return [];
  }
}

/**
 * Get context around a match
 */
function getContext(content, index, contextSize = 80) {
  const start = Math.max(0, index - contextSize);
  const end = Math.min(content.length, index + 80);
  return `...${content.substring(start, end)}...`;
}

/**
 * Get files to check based on arguments
 */
function getFilesToCheck(args) {
  const files = [];

  if (args.includes('--all')) {
    // Get all tracked git files
    const output = execSync('git ls-files', { encoding: 'utf8' });
    for (const line of output.trim().split('\n')) {
      if (line && shouldCheckFile(line)) {
        files.push(line);
      }
    }
  } else if (args.includes('--dir')) {
    // Scan directory recursively
    const dirIndex = args.indexOf('--dir');
    const dirPath = args[dirIndex + 1] || '.';
    const entries = fs.readdirSync(dirPath, { recursive: true });
    for (const entry of entries) {
      const fullPath = path.join(dirPath, entry);
      if (fs.statSync(fullPath).isFile() && shouldCheckFile(fullPath)) {
        files.push(fullPath);
      }
    }
  } else if (args.length > 0) {
    // Explicit files provided
    for (const file of args) {
      if (fs.existsSync(file) && shouldCheckFile(file)) {
        files.push(file);
      }
    }
  } else {
    // Default: check staged files
    try {
      const output = execSync('git diff --cached --name-only', { encoding: 'utf8' });
      for (const line of output.trim().split('\n')) {
        if (line && shouldCheckFile(line)) {
          files.push(line);
        }
      }
    } catch (error) {
      // Not a git repo or no staged files
      console.warn('No git repository or no staged files');
    }
  }

  return files;
}

/**
 * Print findings with severity indicators
 */
function printFindings(allFindings) {
  const severityOrder = ['critical', 'high', 'medium', 'low'];
  let totalBySeverity = { critical: 0, high: 0, medium: 0, low: 0 };

  for (const [file, findings] of Object.entries(allFindings)) {
    for (const finding of findings) {
      totalBySeverity[finding.severity]++;
    }
  }

  // Print summary
  console.log('\n📊 Summary:');
  for (const severity of severityOrder) {
    const count = totalBySeverity[severity];
    if (count > 0) {
      const icon = { critical: '🔴', high: '🟠', medium: '🟡', low: '🟢' }[severity];
      console.log(`  ${icon} ${severity.toUpperCase()}: ${count}`);
    }
  }

  // Print details for high and critical
  for (const severity of ['critical', 'high']) {
    for (const [file, findings] of Object.entries(allFindings)) {
      for (const finding of findings) {
        if (finding.severity === severity) {
          console.log(`\n🚨 ${severity.toUpperCase()} - ${file}`);
          console.log(`   Pattern: ${finding.secretName}`);
          console.log(`   Line: ${finding.line}`);
          console.log(`   Context: ${finding.context}`);
          console.log(`   Match: ${finding.truncatedSecret}`);
        }
      }
    }
  }
}

// ==================== MAIN ====================

function main() {
  const args = process.argv.slice(2);

  // Check if this is a pre-commit hook context
  const isPreCommit = process.env.HUSKY === '1' || process.argv.includes('--pre-commit');

  console.log('🔍 Scanning for secrets...');

  const filesToCheck = getFilesToCheck(args);

  if (filesToCheck.length === 0) {
    console.log('✅ No files to check');
    return 0;
  }

  console.log(`📁 Checking ${filesToCheck.length} file(s)...\n`);

  const allFindings = {};
  let criticalCount = 0;
  let highCount = 0;

  for (const file of filesToCheck) {
    const findings = analyzeFile(file);

    if (findings.length > 0) {
      allFindings[file] = findings;

      for (const finding of findings) {
        if (finding.severity === 'critical') criticalCount++;
        if (finding.severity === 'high') highCount++;
      }
    }
  }

  // Print findings
  printFindings(allFindings);

  // Return appropriate exit code
  if (criticalCount > 0 || (highCount > 0 && !args.includes('--low-only'))) {
    console.log('\n❌ Secrets detected! Aborting.');
    console.log('   Remove secrets or add them to .gitignore');
    return 1;
  } else if (Object.keys(allFindings).length > 0) {
    console.log('\n⚠️  Some potential secrets found (medium/low severity)');
    console.log('   Review findings manually');
    return args.includes('--strict') ? 1 : 0;
  } else {
    console.log('\n✅ No secrets detected');
    return 0;
  }
}

if (require.main === module) {
  const exitCode = main();
  process.exit(exitCode);
}

module.exports = {
  analyzeFile,
  shouldCheckFile,
  patterns,
  exclusions,
};

