**Create `secrets-manager.js`:**
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Initialize client with appropriate region
const client = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1',
  // Use IAM roles in production, not access keys
});

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache.has(secretName)) {
      const { value, timestamp } = this.cache.get(secretName);
      if (Date.now() - timestamp < this.cacheTTL) {
        return value;
      }
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await client.send(command);

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        // Binary secret
        secret = Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      }

      // Cache the result
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;

    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret "${secretName}" not found in AWS Secrets Manager`);
      }
      throw error;
    }
  }

  async getSecretValue(secretName, key) {
    const secret = await this.getSecret(secretName);
    return secret[key];
  }

  // Clear cache for testing or on demand
  clearCache() {
    this.cache.clear();
  }
}

module.exports = new SecretsManager();
```

