require('dotenv').config();

/**
 * Environment variable validation schema
 */
const schema = {
  NODE_ENV: {
    required: true,
    enum: ['development', 'test', 'production'],
    default: 'development'
  },
  PORT: {
    required: false,
    type: 'number',
    default: 3000
  },
  DATABASE_URL: {
    required: true,
    validator: (value) => {
      if (!value.startsWith('postgres://') && !value.startsWith('mongodb://')) {
        throw new Error('DATABASE_URL must be a valid connection string');
      }
    }
  },
  AWS_ACCESS_KEY_ID: {
    required: process.env.NODE_ENV === 'development', // Only for local dev
    description: 'Not needed in production - use IAM roles'
  },
  AWS_SECRET_ACCESS_KEY: {
    required: process.env.NODE_ENV === 'development',
    description: 'Not needed in production - use IAM roles'
  },
  STRIPE_SECRET_KEY: {
    required: true,
    validator: (value) => {
      if (!value.startsWith('sk_live_') && !value.startsWith('sk_test_')) {
        throw new Error('Invalid Stripe secret key format');
      }
    }
  },
  ANTHROPIC_API_KEY: {
    required: true,
    validator: (value) => {
      if (!value.startsWith('sk-ant-')) {
        throw new Error('Invalid Anthropic API key format');
      }
    }
  },
  JWT_SECRET: {
    required: true,
    minLength: 32,
    description: 'Must be at least 32 characters for secure JWT signing'
  }
};

/**
 * Validate and load configuration
 */
function loadConfig() {
  const config = {};
  const errors = [];

  for (const [key, rules] of Object.entries(schema)) {
    const value = process.env[key] || process.env[key.toLowerCase()];

    // Default value
    if (value === undefined && rules.default !== undefined) {
      config[key] = rules.default;
      continue;
    }

    // Required check
    if (rules.required && value === undefined) {
      errors.push(`${key} is required${rules.description ? ` (${rules.description})` : ''}`);
      continue;
    }

    if (value === undefined) {
      if (!rules.required) {
        config[key] = null;
      }
      continue;
    }

    // Type conversion
    let parsedValue = value;
    if (rules.type === 'number') {
      parsedValue = Number(value);
      if (isNaN(parsedValue)) {
        errors.push(`${key} must be a number`);
        continue;
      }
    }
    if (rules.type === 'boolean') {
      parsedValue = value.toLowerCase() === 'true';
    }

    // Enum validation
    if (rules.enum && !rules.enum.includes(parsedValue)) {
      errors.push(`${key} must be one of: ${rules.enum.join(', ')}`);
      continue;
    }

    // Length validation
    if (rules.minLength && parsedValue.length < rules.minLength) {
      errors.push(`${key} must be at least ${rules.minLength} characters`);
      continue;
    }

    // Custom validator
    if (rules.validator) {
      try {
        rules.validator(parsedValue);
      } catch (error) {
        errors.push(`${key}: ${error.message}`);
        continue;
      }
    }

    config[key] = parsedValue;
  }

  if (errors.length > 0) {
    console.error('❌ Configuration validation failed:');
    errors.forEach(error => console.error(`  - ${error}`));
    throw new Error('Invalid configuration');
  }

  // Redact secrets from logs
  const redactedConfig = { ...config };
  ['DATABASE_URL', 'AWS_SECRET_ACCESS_KEY', 'STRIPE_SECRET_KEY', 
   'ANTHROPIC_API_KEY', 'JWT_SECRET', 'LOGFIRE_TOKEN'].forEach(key => {
    if (redactedConfig[key]) {
      redactedConfig[key] = `[REDACTED:${key}]`;
    }
  });

  console.log('✅ Configuration loaded:', JSON.stringify(redactedConfig, null, 2));

  // Freeze to prevent runtime modification
  return Object.freeze(config);
}

// Singleton config instance
let configInstance;

module.exports = () => {
  if (!configInstance) {
    configInstance = loadConfig();
  }
  return configInstance;
};

// Export raw access for testing (with warning)
module.exports.loadConfig = loadConfig;
```

