### **Option C: Cloud-Native Secrets (Modern Approach)**

**For containers/serverless:**

```javascript
// secrets.js - Abstraction layer for multiple sources
class SecretsProvider {
  constructor() {
    this.providers = [];
  }

  register(provider) {
    this.providers.push(provider);
    return this;
  }

  async get(key) {
    for (const provider of this.providers) {
      try {
        const value = await provider.get(key);
        if (value !== undefined) return value;
      } catch (error) {
        // Try next provider
        continue;
      }
    }
    throw new Error(`Secret not found: ${key}`);
  }
}

// AWS Secrets Manager provider
class AWSSecretsProvider {
  async get(key) {
    const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
    const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    const response = await client.send(new GetSecretValueCommand({ SecretId: key }));
    return JSON.parse(response.SecretString);
  }
}

// Environment variable provider (fallback)
class EnvSecretsProvider {
  async get(key) {
    const envKey = key.replace(/\//g, '_').toUpperCase();
    return process.env[envKey];
  }
}

// Docker/K8s Secrets provider (from mounted files)
class FileSecretsProvider {
  async get(key) {
    const fs = require('fs').promises;
    const secretsPath = process.env.SECRETS_PATH || '/run/secrets';
    try {
      const filePath = `${secretsPath}/${key}`;
      const value = await fs.readFile(filePath, 'utf-8');
      return value.trim();
    } catch {
      return undefined;
    }
  }
}

// Build the provider chain
const secrets = new SecretsProvider()
  .register(new FileSecretsProvider())      // 1. Check file secrets (K8s/Docker)
  .register(new AWSSecretsProvider())        // 2. Check AWS Secrets Manager
  .register(new EnvSecretsProvider());       // 3. Check environment variables

module.exports = secrets;
```

