#!/bin/bash
# Pre-commit hook to detect secrets

echo "🔍 Checking for secrets..."

# Patterns to detect
PATTERNS=(
    "password\s*=\s*['\"][^'\"]+['\"]"
    "secret.*=\s*['\"][^'\"]+['\"]"  
    "api_key\s*=\s*['\"][^'\"]+['\"]"
    "access_key\s*=\s*['\"][^'\"]+['\"]"
    "sk_live_[a-zA-Z0-9]+"
    "sk_test_[a-zA-Z0-9]+"
    "AKIA[0-9A-Z]{16}"
    "postgresql://[^@]+:[^@]+@"
    "mysql://[^@]+:[^@]+@"
)

FOUND_SECRETS=0

for pattern in "${PATTERNS[@]}"; do
    if git diff --cached --name-only -z -- '*.js' '*.json' '*.env*' '*.ts' '*.tsx' 2>/dev/null | \
       xargs -0 grep -Ei "$pattern" 2>/dev/null; then
        FOUND_SECRETS=1
    fi
done

if [ $FOUND_SECRETS -eq 1 ]; then
    echo "❌ WARNING: Potential secrets detected in staged files!"
    echo "   Please remove secrets before committing."
    echo "   Use tools like 'git-secrets' or 'trufflehog' for scanning."
    exit 1
fi

echo "✅ No secrets detected"
exit 0
```

