// scripts/check-secrets.js
const fs = require('fs');
const path = require('path');

const SECRET_PATTERNS = [
  /password\s*=\s*['"]?[^'"\s]+/i,
  /secret\s*=\s*['"][^'"]{20,}['"]/i,
  /api[_-]?key\s*=\s*['"][^'"]{20,}['"]/i,
  /access[_-]?key[_-]?id\s*=\s*[A-Z0-9]{20}/i,
  /sk_[a-z0-9]{32,}/i, // Stripe
  /AKIA[0-9A-Z]{16}/i, // AWS access key
  /postgresql?:\/\/[^@]+:[^@]+@/i, // DB URLs with credentials
];

function checkFileForSecrets(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n');
  const secretsFound = [];

  lines.forEach((line, index) => {
    SECRET_PATTERNS.forEach(pattern => {
      if (pattern.test(line) && !line.trim().startsWith('#')) {
        secretsFound.push({
          line: index + 1,
          content: line.trim(),
          pattern: pattern.toString()
        });
      }
    });
  });

  return secretsFound;
}

function scanDirectory(dir, excludeDirs = ['node_modules', '.git']) {
  let results = [];
  const files = fs.readdirSync(dir);

  files.forEach(file => {
    const fullPath = path.join(dir, file);
    const stat = fs.statSync(fullPath);

    if (stat.isDirectory() && !excludeDirs.includes(file)) {
      results = results.concat(scanDirectory(fullPath, excludeDirs));
    } else if (file.match(/\.(js|json|env|yml|yaml|config)$/)) {
      const secrets = checkFileForSecrets(fullPath);
      if (secrets.length > 0) {
        results.push({ file: fullPath, secrets });
      }
    }
  });

  return results;
}

// Run scan
const results = scanDirectory(process.cwd());
if (results.length > 0) {
  console.error('🚨 SECRETS DETECTED:');
  results.forEach(({ file, secrets }) => {
    console.error(`\n📁 ${file}`);
    secrets.forEach(secret => {
      console.error(`   Line ${secret.line}: ${secret.content}`);
    });
  });
  process.exit(1);
} else {
  console.log('✅ No secrets detected');
  process.exit(0);
}
