// secrets.js - Production secret management
const { SSMClient, GetParameterCommand } = require('@aws-sdk/client-ssn');

// Cache secrets to reduce API calls
const secretCache = new Map();
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

class SecretsManager {
  constructor() {
    this.ssmClient = new SSMClient({
      region: process.env.AWS_REGION || 'us-west-2',
    });
  }

  async getSecret(name, useCache = true) {
    // Check cache first
    if (useCache && secretCache.has(name)) {
      const cached = secretCache.get(name);
      if (Date.now() - cached.timestamp < CACHE_TTL) {
        return cached.value;
      }
    }

    try {
      const command = new GetParameterCommand({
        Name: name,
        WithDecryption: true,
      });

      const response = await this.ssmClient.send(command);
      const value = response.Parameter.Value;

      // Cache the value
      secretCache.set(name, {
        value,
        timestamp: Date.now(),
      });

      return value;
    } catch (error) {
      console.error(`Failed to fetch secret ${name}:`, error.message);
      throw new Error(`Unable to retrieve secret: ${name}`);
    }
  }

  async getMultipleSecrets(names) {
    const secrets = await Promise.all(
      names.map(name => this.getSecret(name))
    );
    return Object.fromEntries(names.map((name, i) => [name, secrets[i]]));
  }
}

module.exports = new SecretsManager();
```

