class SecretsLoader {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await secretsClient.send(command);

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = JSON.parse(
          Buffer.from(response.SecretBinary, 'base64').toString('utf-8')
        );
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret '${secretName}':`, error.message);

      // In production, fail fast or use fallback
      if (process.env.NODE_ENV === 'production') {
        throw new Error(`Critical: Secret '${secretName}' unavailable`);
      }

      // Development fallback
      console.warn(`Using fallback values for ${secretName}`);
      return {
        database_url: 'postgresql://localhost:5432/dev',
