```javascript
const logger = require('./logger');

// NEVER log actual secret values
const sanitizeSecrets = (obj) => {
  const sanitized = {};
  for (const key in obj) {
    const value = obj[key];
    if (typeof value === 'string' && value.length > 4) {
      sanitized[key] = `${value.substring(0, 4)}...${value.substring(value.length - 4)}`;
    } else {
      sanitized[key] = '[REDACTED]';
    }
  }
  return sanitized;
};

// Load based on environment
const loadSecrets = async () => {
  const env = process.env.NODE_ENV || 'development';

  try {
    switch (env) {
      case 'production':
        return await loadFromSecretsManager();
      case 'staging':
        return await loadFromVault();
      case 'development':
        return loadFromEnv();
      default:
        throw new Error(`Unknown environment: ${env}`);
    }
  } catch (error) {
    logger.error('Failed to load secrets', { 
      environment: env,
      error: error.message 
    });
    throw error;
  }
};

const loadFromEnv = () => {
  const required = ['DATABASE_URL', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];
  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing environment variables: ${missing.join(', ')}`);
  }

  return {
    database: { url: process.env.DATABASE_URL },
    anthropic: { apiKey: process.env.ANTHROPIC_API_KEY },
    stripe: { secretKey: process.env.STRIPE_SECRET_KEY }
  };
};

const loadFromSecretsManager = async () => {
  const AWS = require('@aws-sdk/client-secrets-manager');
  const { SecretsManagerClient, GetSecretValueCommand } = AWS;

  const client = new SecretsManagerClient({ 
    region: process.env.AWS_REGION 
  });

  // Use IAM role, not credentials
  const secretName = `prod/${process.env.APP_NAME || 'app'}/secrets`;

  const response = await client.send(
    new GetSecretValueCommand({ SecretId: secretName })
  );

  return JSON.parse(response.SecretString);
};

const loadFromVault = async () => {
  const nodeVault = require('node-vault');

  const vault = nodeVault({
    endpoint: process.env.VAULT_ADDR,
    role: process.env.VAULT_ROLE,
    auth: { type: 'iam' }
  });

  const result = await vault.read(`secret/data/staging/app`);
  return result.data.data;
};

// Singleton pattern
let secretsCache = null;

module.exports = {
  getSecrets: async () => {
    if (!secretsCache) {
      secretsCache = await loadSecrets();
      logger.info('Secrets loaded successfully', {
        keys: Object.keys(secretsCache),
      });
    }
    return secretsCache;
  },

  // Get cached secrets
  getCached: () => secretsCache,

  // Rotate secrets (triggered by external event)
  rotateSecrets: async () => {
    logger.info('Rotating secrets...');
    secretsCache = await loadSecrets();
    logger.info('Secrets rotated successfully');
  }
};
```

