    write: (message) => logger.info(message.trim())
  }
}));

// Body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Timeout middleware
app.use(timeout('30s'));
app.use((req, res, next) => {
  if (!req.timedout) next();
});

// Input sanitization
app.use(mongoSanitize());
app.use(xss());

// ============================================
// VALIDATION MIDDLEWARE
// ============================================
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logSecurityEvent('VALIDATION_ERROR', {
      errors: errors.array(),
      ip: req.ip,
      path: req.path
    });
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// ============================================
// AUTHENTICATION & AUTHORIZATION MIDDLEWARE
// ============================================

// Note: In production, implement proper JWT authentication
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    logSecurityEvent('AUTH_FAILED', {
      reason: 'Missing or invalid authorization header',
      ip: req.ip,
      path: req.path
    });
    return res.status(401).json({ 
      error: 'Authentication required',
      code: 'AUTH_MISSING'
    });
  }

  const token = authHeader.substring(7);

  try {
    // Verify token (implement proper JWT verification)
    // const decoded = jwt.verify(token, process.env.JWT_SECRET);
    // For demo, we'll skip actual verification
    req.user = { id: 1, role: 'admin' }; // Placeholder
    next();
  } catch (error) {
    logSecurityEvent('AUTH_FAILED', {
      reason: 'Invalid or expired token',
      ip: req.ip,
      path: req.path
    });
    return res.status(401).json({ 
      error: 'Invalid or expired token',
      code: 'AUTH_INVALID'
    });
  }
};

const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ 
        error: 'Authentication required',
        code: 'AUTH_REQUIRED'
      });
    }
    if (!roles.includes(req.user.role)) {
      logSecurityEvent('AUTHORIZATION_FAILED', {
        userRole: req.user.role,
        requiredRoles: roles,
        ip: req.ip,
        path: req.path
      });
      return res.status(403).json({ 
        error: 'Insufficient permissions',
        code: 'AUTH_INSUFFICIENT'
      });
    }
    next();
  };
};

// ============================================
// ROUTES
// ============================================

// Health check (public)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0'
  });
});

// Users endpoint (protected)
app.get('/users', [
  authenticate,
  authorize('admin', 'user-manager'),
  query('id').optional().isInt({ min: 1 }),
  query('email').optional().isEmail(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt()
], validateRequest, (req, res) => {
  logSecurityEvent('USER_DATA_ACCESS', {
    userId: req.user.id,
    userRole: req.user.role,
    ip: req.ip,
    filters: sanitizeForLogging(req.query)
  });

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply filters
  let filteredUsers = users;
  if (req.query.id) {
    filteredUsers = filteredUsers.filter(u => u.id === parseInt(req.query.id));
  }
  if (req.query.email) {
    filteredUsers = filteredUsers.filter(u => u.email === req.query.email);
  }
  if (req.query.limit) {
    filteredUsers = filteredUsers.slice(0, req.query.limit);
  }

  res.json({
    data: filteredUsers,
    count: filteredUsers.length,
    timestamp: new Date().toISOString()
  });
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Resource not found',
    path: req.path,
    method: req.method
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Don't log in tests to avoid noise
  if (process.env.NODE_ENV !== 'test') {
    logger.error('Error occurred', {
      message: err.message,
      stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
      url: req.url,
      method: req.method,
      ip: req.ip,
      headers: sanitizeForLogging(req.headers)
    });
  }

  const statusCode = err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: {
      message: isDevelopment ? err.message : 'An error occurred. Please try again later.',
      statusCode,
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// ============================================
// SERVER STARTUP
// ============================================
if (require.main === module) {
  const PORT = process.env.PORT || 3000;

  app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT}`, {
      environment: process.env.NODE_ENV || 'development',
      timestamp: new Date().toISOString()
    });
  });
}

module.exports = app;

# Migration Guide: From app.js to app.secure.js

This guide helps you migrate from the basic `app.js` to the secure `app.secure.js` implementation.

## Quick Start

### 1. Install Required Dependencies

```bash
npm install helmet express-rate-limit cors morgan express-validator winston express-mongo-sanitize xss dotenv connect-timeout
```

### 2. Create Environment File

```bash
cp .env.example .env
```

Edit `.env` with your actual configuration:

```bash
NODE_ENV=development
PORT=3000
JWT_SECRET=your_super_secret_jwt_key_minimum_32_characters
ALLOWED_ORIGINS=http://localhost:3000
```

### 3. Replace app.js with app.secure.js

```bash
mv app.js app.old.js
mv app.secure.js app.js
```

### 4. Update Your Tests

If you have tests, update the import:

```javascript
// Before
const app = require('../app');

// After
const app = require('../app');
```

The secure version maintains the same exports, so tests should work with minimal changes.

## Step-by-Step Migration

### Phase 1: Core Security (Do First)

#### Install Security Middleware
```bash
npm install helmet express-rate-limit express-validator
```

#### Add to app.js
```javascript
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

