    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply filters
  let filteredUsers = users;
  if (req.query.id) {
    filteredUsers = filteredUsers.filter(u => u.id === parseInt(req.query.id));
  }
  if (req.query.email) {
    filteredUsers = filteredUsers.filter(u => u.email === req.query.email);
  }
  if (req.query.limit) {
    filteredUsers = filteredUsers.slice(0, req.query.limit);
  }

  res.json({
    data: filteredUsers,
    count: filteredUsers.length,
    timestamp: new Date().toISOString()
  });
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Resource not found',
    path: req.path,
    method: req.method
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Don't log in tests to avoid noise
  if (process.env.NODE_ENV !== 'test') {
    logger.error('Error occurred', {
      message: err.message,
      stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
      url: req.url,
      method: req.method,
      ip: req.ip,
      headers: sanitizeForLogging(req.headers)
    });
  }

  const statusCode = err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: {
      message: isDevelopment ? err.message : 'An error occurred. Please try again later.',
      statusCode,
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// ============================================
// SERVER STARTUP
// ============================================
if (require.main === module) {
  const PORT = process.env.PORT || 3000;

  app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT}`, {
      environment: process.env.NODE_ENV || 'development',
      timestamp: new Date().toISOString()
    });
  });
}

module.exports = app;

