/**
 * Secure Secrets Management Module
 * 
 * This module provides a secure interface for loading and accessing secrets
 * with support for multiple sources (AWS Secrets Manager, .env files)
 * and runtime encryption protection.
 */

const AWS = require('aws-sdk');
const crypto = require('crypto');

class SecretsManager {
  constructor(options = {}) {
    this.cache = new Map();
    this.cacheTTL = options.cacheTTL || 300000; // 5 minutes default
    this.encryptionKey = options.encryptionKey || process.env.SECRETS_ENCRYPTION_KEY;
    this.useAWS = options.useAWS !== false && process.env.NODE_ENV === 'production';

    // AWS Secrets Manager client
    this.secretsClient = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    // Lock to prevent multiple simultaneous fetches
    this.pendingFetches = new Map();
  }

  /**
   * Get a secret by name
   * Caches results and supports multiple sources
   */
  async get(secretName, options = {}) {
    const { allowCache = true, required = false, defaultValue = undefined } = options;

    // Check cache first
    if (allowCache && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    // Prevent concurrent fetches for same secret
    if (this.pendingFetches.has(secretName)) {
      return this.pendingFetches.get(secretName);
    }

    try {
      const fetchPromise = this._fetchSecret(secretName, options);
      this.pendingFetches.set(secretName, fetchPromise);

      const secret = await fetchPromise;

      // Cache the result
      if (allowCache) {
        this.cache.set(secretName, {
          value: secret,
          timestamp: Date.now()
        });
      }

      return secret;
    } finally {
      this.pendingFetches.delete(secretName);
    }
  }

  /**
   * Fetch secret from various sources in priority order
   */
  async _fetchSecret(secretName, options) {
    // Priority 1: AWS Secrets Manager (production only)
    if (this.useAWS) {
      try {
        const awsSecret = await this._getFromAWS(secretName);
        return awsSecret;
      } catch (error) {
        if (error.code !== 'ResourceNotFoundException') {
          console.error(`Error fetching from AWS Secrets Manager: ${error.message}`);
        }
        // Fall through to other sources
      }
    }

    // Priority 2: Environment variables (already loaded from .env)
    if (process.env[secretName]) {
      return process.env[secretName];
    }

    // Priority 3: Default value
    if (options.defaultValue !== undefined) {
      return options.defaultValue;
    }

    // Required secret not found
    if (options.required) {
      throw new Error(`Required secret '${secretName}' not found in any source`);
    }

    return null;
  }

  /**
   * Fetch secret from AWS Secrets Manager
   */
  async _getFromAWS(secretName) {
    const params = {
      SecretId: secretName,
      VersionStage: 'AWSCURRENT' // Always get the current version
    };

    const data = await this.secretsClient.getSecretValue(params).promise();

    if ('SecretString' in data) {
      return data.SecretString;
    } else {
      const buff = Buffer.from(data.SecretBinary, 'base64');
      return buff.toString('utf-8');
    }
  }

  /**
   * Get multiple secrets at once
   */
  async getMany(secretNames, options = {}) {
    const promises = secretNames.map(name => this.get(name, options));
    return Promise.all(promises);
  }

  /**
   * Validate that all required secrets are present
   */
  async validateRequired(secrets) {
    const missing = [];
    const results = {};

    for (const secretName of secrets) {
      try {
        const value = await this.get(secretName, { required: true });
        results[secretName] = value;
      } catch (error) {
        missing.push(secretName);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    return results;
  }

  /**
   * Get secret with runtime encryption protection
   * Decrypts only when needed and doesn't store decrypted value
   */
  async getEncrypted(secretName, options = {}) {
    const encryptedValue = await this.get(secretName, options);

    if (!encryptedValue) {
      return null;
    }

    // Decrypt the value
    try {
      return this._decrypt(encryptedValue);
    } catch (error) {
      throw new Error(`Failed to decrypt secret '${secretName}': ${error.message}`);
    }
  }

  /**
   * Encrypt a value (admin utility)
   */
  encryptValue(value) {
    if (!this.encryptionKey) {
      throw new Error('Encryption key not configured');
    }

    const algorithm = 'aes-256-gcm';
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv(algorithm, Buffer.from(this.encryptionKey), iv);

    let encrypted = cipher.update(value, 'utf8', 'hex');
    encrypted += cipher.final('hex');

    const authTag = cipher.getAuthTag();

    return {
      encrypted,
      iv: iv.toString('hex'),
      authTag: authTag.toString('hex'),
      algorithm
    };
  }

  /**
   * Decrypt a value
   */
  _decrypt(encryptedObj) {
    if (!this.encryptionKey) {
      throw new Error('Encryption key not configured');
    }

    const algorithm = encryptedObj.algorithm || 'aes-256-gcm';
    const decipher = crypto.createDecipheriv(
      algorithm,
      Buffer.from(this.encryptionKey),
      Buffer.from(encryptedObj.iv, 'hex')
    );

    decipher.setAuthTag(Buffer.from(encryptedObj.authTag, 'hex'));

    let decrypted = decipher.update(encryptedObj.encrypted, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return decrypted;
  }

  /**
   * Clear cache (useful for secret rotation)
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Rotate a secret
   */
  async rotate(secretName, newValue) {
    if (this.useAWS) {
      const params = {
        SecretId: secretName,
        SecretString: newValue
      };

      await this.secretsClient.updateSecret(params).promise();
    } else {
      // In development, just clear cache and update process.env
      this.clearCache();
      process.env[secretName] = newValue;
    }
  }

  /**
   * Health check for secrets manager
   */
  async healthCheck() {
    if (this.useAWS) {
      try {
        await this.secretsClient.listSecrets({ MaxResults: 1 }).promise();
        return { status: 'healthy', provider: 'AWS Secrets Manager' };
      } catch (error) {
        return { status: 'unhealthy', provider: 'AWS Secrets Manager', error: error.message };
      }
    }

    return { status: 'healthy', provider: 'Environment Variables' };
  }
}

// Export singleton instance
const secretsManager = new SecretsManager();

module.exports = {
  SecretsManager,
  secretsManager
};

/**
 * Centralized Configuration Management
 * 
 * This module provides a secure interface for all application configuration
 * including secrets, environment variables, and runtime configuration.
 */

const { secretsManager } = require('./secrets');

// Configuration schema with validation
const configSchema = {
  // Server Configuration
  NODE_ENV: {
    required: true,
    defaultValue: 'development',
    validate: (value) => ['development', 'staging', 'production', 'test'].includes(value)
  },
  PORT: {
    required: false,
    defaultValue: 3000,
    type: 'number'
  },
  APP_VERSION: {
    required: false,
    defaultValue: '1.0.0'
  },
  LOG_LEVEL: {
    required: false,
    defaultValue: 'info',
    validate: (value) => ['error', 'warn', 'info', 'debug'].includes(value)
  },

  // Security Configuration
  JWT_SECRET: {
    required: true,
    sensitive: true,
    minLength: 32 // Minimum 32 characters for security
  },
  JWT_EXPIRES_IN: {
    required: false,
    defaultValue: '1h'
  },
  ALLOWED_ORIGINS: {
    required: false,
    defaultValue: 'http://localhost:3000',
    type: 'array' // Will be split by comma
  },

  // Database Configuration
  DATABASE_URL: {
    required: true,
    sensitive: true
  },
  DATABASE_POOL_MIN: {
    required: false,
    defaultValue: 2,
    type: 'number'
  },
  DATABASE_POOL_MAX: {
    required: false,
    defaultValue: 10,
    type: 'number'
  },

  // AWS Configuration
  AWS_ACCESS_KEY_ID: {
    required: true,
    sensitive: true
  },
  AWS_SECRET_ACCESS_KEY: {
    required: true,
    sensitive: true
  },
  AWS_REGION: {
    required: false,
    defaultValue: 'us-east-1'
  },

  // External API Keys
  ANTHROPIC_API_KEY: {
    required: true,
    sensitive: true
  },
  STRIPE_SECRET_KEY: {
    required: true,
    sensitive: true
  },
  LOGFIRE_TOKEN: {
    required: true,
    sensitive: true
  },

  // Secrets Manager
  USE_AWS_SECRETS_MANAGER: {
    required: false,
    defaultValue: false,
    type: 'boolean'
  },
  SECRETS_ENCRYPTION_KEY: {
    required: false,
    sensitive: true
  }
};

class Configuration {
  constructor() {
    this._config = {};
    this._initialized = false;
    this._watchers = [];
  }

  /**
   * Initialize configuration
   */
  async initialize(options = {}) {
    if (this._initialized) {
      return this._config;
    }

    const environment = process.env.NODE_ENV || 'development';
    const useAWS = options.useAWS !== undefined ? options.useAWS : environment === 'production';

    // Configure secrets manager
    if (process.env.SECRETS_ENCRYPTION_KEY) {
      // Encryption key is set
    }

    try {
      // Validate and load all configuration
      for (const [key, schema] of Object.entries(configSchema)) {
        this._config[key] = await this._loadConfigValue(key, schema);
      }

      // Validate cross-cutting concerns
      this._validateConfiguration();

      this._initialized = true;

      return this._config;
    } catch (error) {
      throw new Error(`Configuration initialization failed: ${error.message}`);
    }
  }

  /**
   * Load a single configuration value
   */
  async _loadConfigValue(key, schema) {
    let value;

    // Get value from environment or secrets manager
    try {
      value = await secretsManager.get(key, {
        required: schema.required,
        defaultValue: schema.defaultValue
      });
    } catch (error) {
      if (schema.required !== false) {
        throw new Error(`Required configuration '${key}' is missing`);
      }
      value = schema.defaultValue;
    }

    // Type conversion
    if (schema.type === 'number' && value) {
      value = parseInt(value, 10);
      if (isNaN(value)) {
        throw new Error(`Configuration '${key}' must be a number`);
      }
    }

    if (schema.type === 'boolean' && value) {
      value = value === 'true' || value === true || value === 1;
    }

    if (schema.type === 'array' && value && typeof value === 'string') {
      value = value.split(',').map(v => v.trim());
    }

    // Custom validation
    if (schema.validate && value !== undefined && value !== null) {
      if (!schema.validate(value)) {
        throw new Error(`Configuration '${key}' has an invalid value: ${value}`);
      }
    }

    // Length validation
    if (schema.minLength && value && value.length < schema.minLength) {
      throw new Error(`Configuration '${key}' must be at least ${schema.minLength} characters`);
    }

    return value;
  }

  /**
   * Validate cross-cutting configuration rules
   */
  _validateConfiguration() {
    // Production environment checks
    if (this._config.NODE_ENV === 'production') {
      // Ensure JWT_SECRET is not a default value
      if (this._config.JWT_SECRET.includes('your_') || this._config.JWT_SECRET.includes('example')) {
        throw new Error('JWT_SECRET must not use default/example values in production');
      }

      // Ensure HTTPS
      if (!process.env.FORCE_HTTPS && this._config.NODE_ENV === 'production') {
        console.warn('Warning: FORCE_HTTPS not set in production');
      }
    }

    // AWS credentials must be present together
    if (this._config.AWS_ACCESS_KEY_ID && !this._config.AWS_SECRET_ACCESS_KEY) {
      throw new Error('AWS_SECRET_ACCESS_KEY is required when AWS_ACCESS_KEY_ID is set');
    }

    if (this._config.AWS_SECRET_ACCESS_KEY && !this._config.AWS_ACCESS_KEY_ID) {
      throw new Error('AWS_ACCESS_KEY_ID is required when AWS_SECRET_ACCESS_KEY is set');
    }
  }

  /**
   * Get a configuration value
   */
  get(key) {
    if (!this._initialized) {
      throw new Error('Configuration not initialized. Call initialize() first.');
    }

    if (key === '*') {
      // Return all non-sensitive config
      const safeConfig = {};
      for (const [k, v] of Object.entries(this._config)) {
        if (!configSchema[k]?.sensitive) {
          safeConfig[k] = v;
        }
      }
      return safeConfig;
    }

    const value = this._config[key];

    if (value === undefined) {
      throw new Error(`Configuration '${key}' not found`);
    }

    return value;
  }

  /**
   * Check if configuration is initialized
   */
  isInitialized() {
    return this._initialized;
  }

  /**
   * Reload configuration (useful for secret rotation)
   */
  async reload() {
    this._initialized = false;
    this._config = {};
    secretsManager.clearCache();
    return this.initialize();
  }

  /**
   * Watch for configuration changes (for hot-reload in dev)
   */
  watch(callback) {
    this._watchers.push(callback);
  }

  /**
   * Get all sensitive configuration keys
   */
  getSensitiveKeys() {
    return Object.keys(configSchema).filter(key => configSchema[key].sensitive);
  }

  /**
   * Validate that all sensitive values are set
   */
  async validateAllSensitive() {
    const sensitiveKeys = this.getSensitiveKeys();
    const missing = [];

    for (const key of sensitiveKeys) {
      if (!this._config[key]) {
        missing.push(key);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing sensitive configuration: ${missing.join(', ')}`);
    }

    return true;
  }

  /**
   * Export configuration for debugging (sanitized)
   */
  debugInfo() {
    const info = {};
    for (const [key, schema] of Object.entries(configSchema)) {
      const value = this._config[key];
      if (schema.sensitive) {
        info[key] = `[${schema.type || 'string'}: REDACTED]`;
      } else {
        info[key] = value;
      }
    }
    return info;
  }
}

// Export singleton instance
