```javascript
// config/secrets-manager.js
const AWS = require('aws-sdk');
const { parse } = require('pg-connection-string');

async function loadFromSecretsManager(secretName) {
  const client = new AWS.SecretsManager({ 
    region: process.env.AWS_REGION || 'us-east-1' 
  });

  try {
    const data = await client.getSecretValue({ SecretId: secretName }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    }

    // Handle binary secrets
    const buff = Buffer.from(data.SecretBinary, 'base64');
    return JSON.parse(buff.toString('ascii'));

  } catch (err) {
    if (err.code === 'ResourceNotFoundException') {
      console.error(`Secret not found: ${secretName}`);
    } else if (err.code === 'DecryptionFailureException') {
      console.error('Secrets Manager cannot decrypt');
    } else if (err.code === 'AccessDeniedException') {
      console.error('Access denied to Secrets Manager');
    }
    throw err;
  }
}

async function loadProductionSecrets() {
  // Fetch secrets from AWS Secrets Manager
  const secrets = await loadFromSecretsManager('myapp/production');

  // Validate required secrets exist
  if (!secrets.database_url || !secrets.jwt_secret) {
    throw new Error('Required secrets missing from Secrets Manager');
  }

  // Set environment variables
  process.env.DATABASE_URL = secrets.database_url;
  process.env.JWT_SECRET = secrets.jwt_secret;
  process.env.AWS_ACCESS_KEY_ID = secrets.aws_access_key_id;
  process.env.AWS_SECRET_ACCESS_KEY = secrets.aws_secret_access_key;
  process.env.ANTHROPIC_API_KEY = secrets.anthropic_api_key;
  process.env.STRIPE_SECRET_KEY = secrets.stripe_secret_key;
  // ... etc

  return secrets;
}

// Load Python-style overrides for local development
async function loadSecrets() {
  if (process.env.NODE_ENV === 'production') {
