### **Detection Script: Find Leaked Secrets**

```javascript
// scripts/detect-secrets.js
const fs = require('fs');
const path = require('path');

const SECRET_PATTERNS = [
  { name: 'AWS Access Key', pattern: /AKIA[0-9A-Z]{16}/i },
  { name: 'AWS Secret Key', pattern: /[A-Za-z0-9/+=]{40}/i },
  { name: 'Database URL', pattern: /postgres:\/\/\w+:[^@]+@/i },
  { name: 'API Key (sk-ant)', pattern: /sk-ant-[a-zA-Z0-9_-]{20,}/ },
  { name: 'Stripe Key', pattern: /sk_(live|test)_[a-zA-Z0-9]{20,}/ },
  { name: 'JWT Secret', pattern: /jwt.*=.*['"][^'"]{20,}['"]/i },
  { name: 'Canary Value', pattern: /canary/i },
];

function scanFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const findings = [];

  SECRET_PATTERNS.forEach(({ name, pattern }) => {
    const matches = content.match(new RegExp(pattern, 'gi'));
    if (matches) {
      matches.forEach(match => {
        findings.push({ type: name, match });
      });
    }
  });

  return findings;
}

function scanDirectory(dir) {
  const results = {};

  function walk(currentDir) {
    const files = fs.readdirSync(currentDir);

    files.forEach(file => {
      const filePath = path.join(currentDir, file);
      const stat = fs.statSync(filePath);

      if (stat.isDirectory() && !file.startsWith('.') && file !== 'node_modules') {
        walk(filePath);
      } else if (stat.isFile() && /\.(js|ts|json|yml|yaml|env|txt|md)$/.test(file)) {
        const findings = scanFile(filePath);
        if (findings.length > 0) {
          results[filePath] = findings;
        }
      }
    });
  }

  walk(dir);
  return results;
}

const findings = scanDirectory(process.cwd());

if (Object.keys(findings).length > 0) {
  console.log('\n⚠️  POTENTIAL SECRETS DETECTED:\n');
  console.log(JSON.stringify(findings, null, 2));
  process.exit(1);
} else {
  console.log('✅ No secrets detected');
  process.exit(0);
}
