const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

// Secret generators
function generateAWSAccessKeyId() {
  return 'AKIA' + crypto.randomBytes(12).toString('base64')
    .replace(/[+/=]/g, '')
    .substring(0, 16);
}

function generateAWSSecretAccessKey() {
  return crypto.randomBytes(40).toString('base64')
    .replace(/=/g, '')
    .substring(0, 40);
}

function generateApiKey(prefix = 'sk') {
  return crypto.randomBytes(32).toString('base64')
    .replace(/[+/=]/g, '')
    .padStart(40, prefix);
}

function generateStripeKey(isTest = false) {
  return `sk_${isTest ? 'test' : 'live'}_${crypto.randomBytes(24).toString('base64')
    .replace(/[+/=]/g, '')}`;
}

function generateJWTSecret() {
  return crypto.randomBytes(32).toString('hex');
}

function generateLogfireToken() {
  return crypto.randomBytes(24).toString('hex');
}

function generateDatabasePassword() {
  return crypto.randomBytes(24).toString('base64')
    .replace(/[+/=]/g, '');
}

// Rotation tracker (writes to a secure log, not containing actual values)
class RotationTracker {
  constructor(logPath) {
    this.logPath = logPath;
  }

  logRotation(variable, { timestamp, status, environment, note }) {
    const entry = {
      timestamp,
      variable,
      status,
      environment,
      note,
      // Only hash of new value, for verification (never the actual value)
      verificationHash: null
    };

    const logData = JSON.stringify(entry, null, 2) + '\n';
    fs.appendFileSync(this.logPath, logData);

    console.log(`✓ Rotated: ${variable} [${status}]`);
  }
}

// Main rotation function
