// config/secrets.js
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    const cached = this.cache.get(secretName);

    if (!forceRefresh && cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();
      const secret = JSON.parse(data.SecretString);

      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      this.logAccess(secretName, 'success');
      return secret;
    } catch (error) {
      this.logAccess(secretName, 'failed', error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  logAccess(secretName, status, error = null) {
    // Sanitized logging - never log actual secrets
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      event: 'secret_access',
      secret: secretName, // Only the name, not the value
      status,
      ...(error && { errorCode: error.code })
    }));
  }
}

module.exports = new SecretsManager();
