// config/load-secrets.js
const crypto = require('crypto');
const fs = require('fs');
require('dotenv').config();

class SecureEnvLoader {
  constructor() {
    this.algorithm = 'aes-256-gcm';
    this.keyLength = 32;
    this.ivLength = 16;
    this.saltLength = 64;
  }

  // Decrypt environment file (for local development only)
  decryptEnvFile(encryptedPath, password) {
    const encrypted = fs.readFileSync(encryptedPath, 'utf8');
    const data = JSON.parse(encrypted);

    const key = crypto.scryptSync(password, data.salt, this.keyLength);
    const decipher = crypto.createDecipheriv(
      this.algorithm,
      key,
      Buffer.from(data.iv, 'hex')
    );

    decipher.setAuthTag(Buffer.from(data.authTag, 'hex'));

    let decrypted = decipher.update(data.content, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    // Parse and set environment variables
    const envVars = this.parseEnvString(decrypted);
    Object.assign(process.env, envVars);

    return envVars;
  }

  parseEnvString(str) {
    const result = {};
    str.split('\n').forEach(line => {
      const [key, ...valueParts] = line.split('=');
      if (key && valueParts.length > 0) {
        result[key.trim()] = valueParts.join('=').trim();
      }
    });
    return result;
  }
}

// Only use encryption for local development, never in production
if (process.env.NODE_ENV === 'development') {
  const loader = new SecureEnvLoader();
  const password = process.env.ENCRYPTION_PASSWORD; // From system keychain
  loader.decryptEnvFile('.env.encrypted', password);
}

