```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const AWS = require('aws-sdk');

const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache secrets in memory with TTL
let secretsCache = null;
let cacheExpiry = null;
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function getSecret(secretName, forceRefresh = false) {
  // Return cached value if available and not expired
  if (!forceRefresh && secretsCache && cacheExpiry && Date.now() < cacheExpiry) {
    return secretsCache[secretName];
  }

  try {
    const response = await secretsClient.send(
      new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT'
      })
    );

    const secret = response.SecretString ? JSON.parse(response.SecretString) : null;

    // Update cache
    if (!secretsCache || Date.now() >= cacheExpiry) {
      secretsCache = {};
      cacheExpiry = Date.now() + CACHE_TTL;
    }
    secretsCache[secretName] = secret;

    return secret;
  } catch (error) {
    console.error(`Error retrieving secret ${secretName}:`, error);
    throw new Error(`Failed to retrieve secret: ${secretName}`);
  }
}

async function loadAllSecrets() {
  const requiredSecrets = [
    'prod/app/database',
    'prod/app/stripe',
    'prod/app/anthropic',
    'prod/app/logfire'
  ];

  try {
    const secrets = await Promise.all(
      requiredSecrets.map(name => getSecret(name))
    );

    return {
      database: secrets[0],
      stripe: secrets[1],
      anthropic: secrets[2],
      logfire: secrets[3]
    };
  } catch (error) {
    console.error('Failed to load secrets:', error);
    throw error;
  }
}

// Use IAM roles, not access keys for AWS resources
async function getAwsCredentials() {
  // Don't store AWS credentials - use IAM roles
  const credentials = AWS.config.credentials;
  if (!credentials) {
    throw new Error('AWS credentials not available from IAM role');
  }
  return credentials;
}

module.exports = {
  getSecret,
  loadAllSecrets,
  getAwsCredentials
};
```

