## 🔄 Secret Rotation Strategy

```javascript
// config/secret-rotation.js
class SecretRotator {
  constructor(secretLoader) {
    this.loader = secretLoader;
    this.rotationIntervals = new Map();
  }

  // Set up automatic rotation for high-value secrets
  enableRotation(secretName, intervalMs) {
    if (this.rotationIntervals.has(secretName)) {
      console.warn(`Rotation already enabled for ${secretName}`);
      return;
    }

    const interval = setInterval(async () => {
      try {
        // Force refresh from secrets manager
        await this.loader.getSecret(secretName, true);
        console.log(`Secret rotated: ${secretName}`);
      } catch (error) {
        console.error(`Failed to rotate secret ${secretName}:`, error);
        // Alert monitoring system
      }
    }, intervalMs);

    this.rotationIntervals.set(secretName, interval);
  }

  stopAllRotations() {
    this.rotationIntervals.forEach((interval, secretName) => {
      clearInterval(interval);
      console.log(`Stopped rotation for ${secretName}`);
    });
    this.rotationIntervals.clear();
  }
}

// Usage
const rotator = new SecretRotator(secrets);
rotator.enableRotation('prod/app/stripe', 24 * 60 * 60 * 1000); // Daily
