### 9. **Verbose Error Messages (A05:2021 - Security Misconfiguration)**

**Issue:** Generic error handling isn't implemented, potentially leaking sensitive information.

**Recommended Fix:**
```javascript
// Centralized error handler
app.use((err, req, res, next) => {
  // Log the full error for debugging (not to client)
  console.error('Error:', err);

  // Don't expose stack traces or internal details
  let message = 'An internal server error occurred';
  let status = 500;

  // Handle specific error types
  if (err.name === 'UnauthorizedError') {
    status = 401;
    message = 'Unauthorized access';
  } else if (err.name === 'ValidationError') {
    status = 400;
    message = 'Invalid request data';
  }

  res.status(status).json({
    error: message,
    requestId: req.id // Include request ID for support correlation
  });
});

// Add request ID middleware
const { v4: uuidv4 } = require('uuid');
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});
