/**
 * Secrets Management Module
 * 
 * This module provides secure loading and validation of secrets.
 * Supports multiple sources: AWS Secrets Manager, Parameter Store, or environment variables.
 */

const AWS = require('aws-sdk');

// Secrets cache to reduce API calls
const secretsCache = new Map();
const CACHE_TTL = getCacheTTL();

function getCacheTTL() {
  // Longer cache in production, shorter in development
  const env = process.env.NODE_ENV || 'development';
  return env === 'production' ? 300000 : 60000; // 5 min / 1 min
}

/**
 * Load secrets from AWS Secrets Manager
 */
async function loadFromSecretsManager(secretPrefix = 'production') {
  const client = new AWS.SecretsManager({
    region: process.env.AWS_REGION || 'us-east-1'
  });

  const secrets = {};
  const secretNames = [
    `${secretPrefix}/database`,
    `${secretPrefix}/stripe`,
    `${secretPrefix}/api-keys`
  ];

  for (const secretName of secretNames) {
    try {
      // Check cache first
      const cacheKey = `sm:${secretName}`;
      const cached = secretsCache.get(cacheKey);

      if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
        Object.assign(secrets, cached.value);
        continue;
      }

      // Fetch from Secrets Manager
      const data = await client.getSecretValue({ SecretId: secretName }).promise();
      const secretValue = data.SecretString ? JSON.parse(data.SecretString) : {};

      // Cache the result
      secretsCache.set(cacheKey, { value: secretValue, timestamp: Date.now() });
      Object.assign(secrets, secretValue);

    } catch (err) {
      if (err.code !== 'ResourceNotFoundException') {
        console.error(`Failed to load secret ${secretName}:`, err.message);
      }
    }
  }

  return secrets;
}

/**
 * Load secrets from AWS Systems Manager Parameter Store
 */
async function loadFromParameterStore(path = '/production/') {
  const ssm = new AWS.SSM({ region: process.env.AWS_REGION || 'us-east-1' });

  const secrets = {};
  let nextToken;

  do {
    try {
      const response = await ssm.getParametersByPath({
        Path: path,
        WithDecryption: true,
        Recursive: true,
        NextToken: nextToken
      }).promise();

      response.Parameters.forEach(param => {
        // Remove path prefix and convert to env-like naming
        const key = param.Name.replace(path, '').replace(/\//g, '_').toUpperCase();
        secrets[key] = param.Value;
      });

      nextToken = response.NextToken;
    } catch (err) {
      console.error('Failed to load from Parameter Store:', err.message);
      break;
    }
  } while (nextToken);

  return secrets;
}

/**
 * Load secrets from environment variables (fallback)
 */
function loadFromEnv() {
  const secrets = {};
  const envVars = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'AWS_REGION',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'STRIPE_PUBLISHABLE_KEY',
    'LOGFIRE_TOKEN',
    'JWT_SECRET',
    'SESSION_SECRET',
    'REDIS_URL',
    'SMTP_USER',
    'SMTP_PASSWORD'
  ];

  envVars.forEach(varName => {
    if (process.env[varName]) {
      secrets[varName] = process.env[varName];
    }
  });

  return secrets;
}

/**
 * Validate all required secrets are present
 */
function validateSecrets(secrets, required = {}) {
  const errors = [];

  Object.entries(required).forEach(([key, rules]) => {
    const value = secrets[key];

    if (rules.required && !value) {
      errors.push(`${key}: Required but not set (${rules.description})`);
      return;
    }

    if (value && rules.minLength && value.length < rules.minLength) {
      errors.push(`${key}: Must be at least ${rules.minLength} characters`);
    }

    if (value && rules.pattern && !rules.pattern.test(value)) {
      errors.push(`${key}: Invalid format`);
    }

    // Check for example/default/dummy values
    if (value && rules.checkDefaults) {
      const defaultPatterns = [
        /your_.*_her?e/i,
        /example\.com/,
        /changeme/i,
        /test123/i,
        /secret123/i,
        /xxx/i,
        /^test_/i,
        /placeholder/i
      ];

      if (defaultPatterns.some(pattern => pattern.test(value))) {
        errors.push(`${key}: Contains example/default value`);
      }
    }
  });

  return errors;
}

/**
 * Load secrets from all available sources with priority
 */
async function loadSecrets() {
  const source = process.env.SECRETS_SOURCE || 'env';
  let secrets = {};

  console.log(`Loading secrets from: ${source}`);

  switch (source) {
    case 'aws-secrets-manager':
      secrets = await loadFromSecretsManager(process.env.SECRETS_PREFIX);
      break;
    case 'aws-parameter-store':
      secrets = await loadFromParameterStore(process.env.PARAMETER_PATH);
      break;
    case 'env':
    default:
      secrets = loadFromEnv();
  }

  // Add environment-specific overrides
  if (process.env.NODE_ENV) {
    secrets.NODE_ENV = process.env.NODE_ENV;
  }

  return secrets;
}

/**
 * Initialize secrets with validation
 */
async function initializeSecrets() {
  try {
    const secrets = await loadSecrets();

    // Define required secrets based on environment
    const isProd = secrets.NODE_ENV === 'production';

    const requiredSecrets = {
      DATABASE_URL: {
        required: true,
        description: 'PostgreSQL connection string',
        checkDefaults: true
      },
      JWT_SECRET: {
        required: isProd,
        description: 'JWT signing secret',
        minLength: 32,
        checkDefaults: isProd
      },
      STRIPE_SECRET_KEY: {
        required: isProd,
        description: 'Stripe API secret key',
        pattern: /^sk_(live|test)_[a-zA-Z0-9]{20,}$/,
        checkDefaults: true
      },
      LOGFIRE_TOKEN: {
        required: false,
        description: 'Logfire observability token'
      }
    };

    // Validate secrets
    const errors = validateSecrets(secrets, requiredSecrets);

    if (errors.length > 0) {
      console.error('\n❌ Secrets Validation Failed:\n');
      errors.forEach(err => console.error(`   - ${err}`));
      throw new Error(`Secrets validation failed with ${errors.length} error(s)`);
    }

    console.log('✓ Secrets loaded and validated successfully\n');

    return secrets;

  } catch (err) {
    console.error('\n❌ Failed to initialize secrets:');
    console.error(`   ${err.message}\n`);
    console.error('Please ensure required secrets are configured.\n');

    if (process.env.NODE_ENV === 'production') {
      process.exit(1);
    }

    // In development, return empty object with warning
    console.warn('⚠️  Running in development mode without full secrets\n');
    return {};
  }
}

/**
 * Get a specific secret value
 */
function getSecret(key, secrets) {
  if (!secrets) {
    throw new Error('Secrets not initialized. Call initializeSecrets() first.');
  }

  return secrets[key];
}

/**
 * Redact secrets from logs (for debugging)
 */
function redactSecrets(obj, secrets) {
  if (!obj || typeof obj !== 'object') return obj;

  const sensitiveKeys = [
    'password', 'secret', 'token', 'key', 'auth',
    'access_key', 'secret_key', 'api_key', 'private_key',
    'DATABASE_URL', 'JWT_SECRET', 'STRIPE_SECRET_KEY'
  ];

  const redacted = { ...obj };

  Object.keys(redacted).forEach(key => {
    const lowerKey = key.toLowerCase();
    const isSensitive = sensitiveKeys.some(sensitive => 
      lowerKey.includes(sensitive.toLowerCase())
    );

    if (isSensitive && typeof redacted[key] === 'string') {
      const value = redacted[key];
      redacted[key] = value.substring(0, 3) + '***' + value.substring(value.length - 2);
    }
  });

  return redacted;
}

/**
 * Clear secrets cache (for testing or after rotation)
 */
function clearCache() {
  secretsCache.clear();
  console.log('✓ Secrets cache cleared');
}

module.exports = {
  loadSecrets,
  initializeSecrets,
  getSecret,
  validateSecrets,
  redactSecrets,
  clearCache,
  loadFromSecretsManager,
  loadFromParameterStore,
  loadFromEnv
};

/**
 * Secure Express Application with Proper Secrets Management
 * 
 * This example shows how to properly integrate secrets management
 * into an Express application.
 */

require('dotenv').config(); // Only for local development

const express = require('express');
const { initializeSecrets, getSecret, redactSecrets } = require('./secrets-manager');

let applicationSecrets;

// Initialize application with secrets
async function startServer() {
  try {
    // 🔒 STEP 1: Load and validate secrets at startup
    console.log('=' .repeat(50));
    console.log('Initializing Secure Application');
    console.log('=' .repeat(50));

    applicationSecrets = await initializeSecrets();

    // Create Express app
    const app = express();

    // 🔒 STEP 2: Middleware configuration
    app.use(express.json());

    // Request ID middleware
    app.use((req, res, next) => {
      req.id = Date.now().toString(36) + Math.random().toString(36).substr(2);
      res.setHeader('X-Request-ID', req.id);
      next();
    });

    // Security logger (never logs secrets!)
    const securityLogger = {
      info: (message, meta = {}) => {
        console.log(JSON.stringify({
          level: 'info',
          timestamp: new Date().toISOString(),
          message,
          ...redactSecrets(meta, applicationSecrets)
        }));
      },
      warn: (message, meta = {}) => {
        console.warn(JSON.stringify({
          level: 'warn',
          timestamp: new Date().toISOString(),
          message,
          ...redactSecrets(meta, applicationSecrets)
        }));
      },
      error: (message, meta = {}) => {
        console.error(JSON.stringify({
          level: 'error',
          timestamp: new Date().toISOString(),
          message,
          ...redactSecrets(meta, applicationSecrets)
        }));
      }
    };

    // 🔒 STEP 3: Protected routes using secrets

    // Health check (no secrets needed)
    app.get('/health', (req, res) => {
      res.json({
        status: 'healthy',
        timestamp: new Date().toISOString(),
        requestId: req.id
      });
    });

    // User endpoint (uses database secret)
    app.get('/users', async (req, res) => {
      try {
        // 🔒 Use secret - never expose in response
        const databaseUrl = getSecret('DATABASE_URL', applicationSecrets);

        // Log access (URL is redacted)
        securityLogger.info('User list accessed', {
          requestId: req.id,
          ip: req.ip,
          userAgent: req.get('User-Agent')
        });

        // In real app, would connect to database using the secret
        // const pool = new Pool({ connectionString: databaseUrl });

        res.json([
          { id: 1, name: 'Alice' },
          { id: 2, name: 'Bob' }
        ]);

      } catch (err) {
        securityLogger.error('Failed to fetch users', {
          requestId: req.id,
          error: err.message
          // NEVER log the full error object or secrets!
        });

        res.status(500).json({
          error: 'Internal server error',
          requestId: req.id
        });
      }
    });

    // Payment endpoint (uses Stripe secret)
    app.post('/payment', async (req, res) => {
      try {
        const { amount, currency = 'usd' } = req.body;

        // Validate input
        if (!amount || amount < 0) {
          return res.status(400).json({
            error: 'Invalid amount',
            requestId: req.id
          });
        }

        // 🔒 Use Stripe secret
        const stripeSecretKey = getSecret('STRIPE_SECRET_KEY', applicationSecrets);

        // Log payment attempt (never log card details or the secret)
        securityLogger.info('Payment initiated', {
          requestId: req.id,
          amount,
          currency
        });

        // In real app, would call Stripe API
        // const stripe = require('stripe')(stripeSecretKey);
        // const paymentIntent = await stripe.paymentIntents.create({...});

        // Simulate success
        res.json({
          success: true,
          paymentId: `pi_${Math.random().toString(36).substr(2, 9)}`,
          amount,
          currency
        });

      } catch (err) {
        securityLogger.error('Payment failed', {
          requestId: req.id,
          error: err.message
        });

        res.status(500).json({
          error: 'Payment processing failed',
          requestId: req.id
        });
      }
    });

    // 🔒 STEP 4: Error handler (never exposes secrets)
    app.use((err, req, res, next) => {
      securityLogger.error('Unhandled error', {
        requestId: req.id,
        error: err.message
        // NO stack traces, NO secrets, NO internal paths
      });

      res.status(500).json({
        error: 'An internal server error occurred',
        requestId: req.id
      });
    });

    // 404 handler
    app.use((req, res) => {
      res.status(404).json({
        error: 'Not found',
        requestId: req.id
      });
    });

